(async()=>{await fetch(preview+'/status',{signal:AbortSignal.timeout(5000)});const browser=await chromium.launch({channel:process.env.BROWSER_CHANNEL || 'chrome',headless:true});let results=process.env.RESPONSIVE_RESUME && fs.existsSync(output)?JSON.parse(fs.readFileSync(output,'utf8')).filter(r=>!r.error && !r.overflow && !r.renderError && !r.outside?.length && !r.errors?.length):[];
for(const role of roles){const user={id:'00000000-0000-0000-0000-000000000001',email:'test@example.invalid',aud:'authenticated',role:'authenticated',user_metadata:{role:role==='site'||role==='site-manager'?'site_manager':role,full_name:'Responsive Test'},app_metadata:{provider:'email'}};const exp=Math.floor(Date.now()/1000)+3600,token=Buffer.from('{}').toString('base64url')+'.'+Buffer.from(JSON.stringify({sub:user.id,exp,role:'authenticated'})).toString('base64url')+'.test';
