await page.route('**/rest/v1/**',r=>r.fulfill({json:r.request().headers().accept?.includes('object+json')?(r.request().url().includes('/profiles')?{id:user.id,role:user.user_metadata.role,is_approved:true,full_name:'Responsive Test'}:null):[]}));await page.route('**/auth/v1/**',r=>r.fulfill({json:user}));await page.route('**/api/**',r=>r.fulfill({json:[]}));await page.route('**/reports/management',r=>r.fulfill({json:{generated_at:new Date().toISOString(),projects:[],materials:[],orders:[],payroll:[],people:[]}}));await page.routeWebSocket('**/realtime/**',ws=>ws.close());let errors=[];page.on('pageerror',e=>errors.push(e.message));
for(const file of files('frontend/src/app/'+role).filter(f=>f.endsWith('.tsx')&&!f.includes('_layout'))){const route='/'+path.relative('frontend/src/app',file).replaceAll('\\','/').replace(/\.tsx$/,'').replace(/\/index$/,'').replace(/\[[^\]]+\]/g,'00000000-0000-0000-0000-000000000001');if(process.env.RESPONSIVE_ROUTE && route!==process.env.RESPONSIVE_ROUTE)continue;if(process.env.RESPONSIVE_RESUME && new Set(results.filter(r=>r.route===route).map(r=>r.width)).size===4)continue;errors=[];try{await page.setViewportSize({width:390,height:844});await page.goto(preview+route,{waitUntil:'domcontentloaded',timeout:180000});await page.getByLabel('Open notifications',{exact:true}).first().waitFor({timeout:30000});await page.waitForTimeout(600);
for(const [width,height] of [[320,568],[768,1024],[1024,768],[1440,900]]){await page.setViewportSize({width,height});await page.waitForTimeout(160);const geometry=await page.evaluate(()=>({overflow:document.documentElement.scrollWidth>innerWidth+1,body:document.body.innerText.slice(-180),renderError:document.body.innerText.includes('Uncaught Error')||document.body.innerText.includes('Log 1 of'),outside:[...document.querySelectorAll('input,button,[role="button"]')].filter(e=>{let r=e.getBoundingClientRect();if(!r.width||!r.height||r.right<=0)return false;for(let p=e.parentElement;p;p=p.parentElement){let c=getComputedStyle(p);if(['auto','scroll'].includes(c.overflowX)&&p.scrollWidth>p.clientWidth+1)return false;}return r.left< -1||r.right>innerWidth+1;}).map(e=>e.textContent.slice(0,60))}));results.push({route,width,...geometry,errors:[...errors]});}
console.log(route,errors.length?'ERROR '+errors.join(','):'checked');}catch(e){results.push({route,error:e.message});console.log('FAIL',route,e.message.slice(0,100));if(e.message.includes('ERR_CONNECTION_REFUSED')){await browser.close();throw e;}}fs.writeFileSync(output,JSON.stringify(results,null,2));}
await page.close();}await browser.close();const failed=results.filter(r=>r.error || r.overflow || r.renderError || r.outside?.length || r.errors?.length);
console.log('DONE',results.length,'checks;',failed.length,'failures');
if(failed.length)process.exitCode=1;})().catch(e=>{console.error(e);process.exit(1)});

