const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const ts = require('typescript');
const vm = require('node:vm');
const source = fs.readFileSync(path.join(__dirname, '../src/components/reports/metrics.ts'), 'utf8');
const compiled = ts.transpileModule(source, { compilerOptions: { module: ts.ModuleKind.CommonJS } }).outputText;
const sandbox = { exports: {} }; vm.runInNewContext(compiled, sandbox);
const m = sandbox.exports;
let count = 0;
function test(name, run) { run(); count++; console.log('PASS', name); }
test('Missing and invalid amounts are not zero', () => {
  for (const input of [null, undefined, '', '  ', 'bad', Infinity, false]) assert.equal(m.numeric(input), null);
  assert.equal(m.numeric('0'), 0);
  assert.equal(m.sumKnown([{id:'1',total_amount:null}],m.amount),null);
  assert.equal(m.sumKnown([],m.amount),0);
});
test('Budget comparisons include zero budgets and exclude missing budgets', () => {
  assert.equal(m.overBudget({id:'1', total_budget:0, spent_cost:10}), true);
  assert.equal(m.overBudget({id:'1', total_budget:null, spent_cost:10}), false);
  assert.equal(m.overBudget({id:'1', total_budget:10, spent_cost:10}), false);
});
test('Overdue rules exclude completed/cancelled projects and dates due today', () => {
  for(const state of ['Completed','cancelled','CANCELED']) assert.equal(m.overdueProject({id:'1',status:state,end_date:'2026-01-01'},'2026-02-01'),false);
  assert.equal(m.overdueProject({id:'1',status:'In Progress',end_date:'2026-01-31'},'2026-02-01'),true);
  assert.equal(m.overdueProject({id:'1',status:'In Progress',end_date:'2026-02-01'},'2026-02-01'),false);
});
test('Stock thresholds preserve zero and handle missing values', () => {
  assert.equal(m.stockFlag({id:'1',current_stock:0,minimum_threshold:0}),'Out of stock');
  assert.equal(m.stockFlag({id:'1',current_stock:5,minimum_threshold:5}),'Within threshold');
  assert.equal(m.shortage({id:'1',current_stock:2,minimum_threshold:5}),3);
  assert.equal(m.shortage({id:'1',current_stock:null,minimum_threshold:5}),null);
  assert.equal(m.stock({id:'1',current_stock:0,global_stock_quantity:10}),0);
});
test('Payroll uses actual generated fields and does not classify unknown as pending', () => {
  const row={id:'1',site_id:'site-1',total_amount:0,total_payout:50,total_overtime_hours:4,period_start:null};
  assert.equal(m.siteId(row),'site-1'); assert.equal(m.amount(row),0); assert.equal(m.overtime(row),4);
  assert.equal(m.monthKey(row.period_start),null); assert.equal(m.pendingPay(row),false);
  assert.equal(m.pendingPay({id:'1',status:'Pending'}),true);
});
test('Late delivery excludes delivered and cancelled orders', () => {
  assert.equal(m.lateOrder({id:'1',status:'Pending Delivery',expected_date:'2026-01-01'},'2026-01-02'),true);
  for(const state of ['Delivered','Cancelled','Rejected']) assert.equal(m.lateOrder({id:'1',status:state,expected_date:'2026-01-01'},'2026-01-02'),false);
  assert.equal(m.orderValue({id:'1',quantity_ordered:4,unit_price:20}),80);
  assert.equal(m.orderValue({id:'1',quantity_ordered:4}),null);
});
test('Invalid dates are excluded from month aggregation', () => {
  assert.equal(m.monthKey('2026-02-30'),null); assert.equal(m.monthKey('2026-10-01T00:00:00Z'),'2026-10');
});
test('CSV escapes quotes and neutralizes spreadsheet formulas', () => {
  const output=m.csv(['Name'],[['=1+1'],['test "quoted"'],['  @SUM(A1)']]);
  assert(output.includes('"\'=1+1"')); assert(output.includes('"test ""quoted"""')); assert(output.includes("'  @SUM"));
});
console.log(`${count} reporting calculation tests passed.`);

import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, ActivityIndicator, Pressable, TextInput, Alert, Platform } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { api } from '../../services/api';
import { TopNav } from '@/components/common/TopNav';
import { useResponsive } from '../../hooks/useResponsive';
import { useRouter } from 'expo-router';

export default function MLInsightsDashboard() {
  const [loading, setLoading] = useState(true);
  const [insights, setInsights] = useState<any>(null);
  const [errorMsg, setErrorMsg] = useState('');
  const { isMobile } = useResponsive();
  const router = useRouter();

  // What-If Simulator state
  const [simSqft, setSimSqft] = useState('2000');
  const [simQuality, setSimQuality] = useState('Standard');
  const [simulating, setSimulating] = useState(false);
  const [simResult, setSimResult] = useState<number | null>(null);

  const runSimulator = async () => {
    setSimulating(true);
    try {
      const res = await api.post('/ai/predict-cost', {
        square_footage: Number(simSqft) || 2000,
        num_floors: 1,
        location: 'Colombo',
        project_type: 'Residential',
        quality_tier: simQuality,
        site_condition: 'Level',
        structure_type: 'Concrete Frame',
        finishing_flooring: 'Tile',
        finishing_sanitary: 'Standard',
        finishing_electrical: 'Standard',
        target_timeline: 'Normal'
      });
      setSimResult(res.estimated_cost);
    } catch (e: any) {
      if (Platform.OS === 'web') window.alert(e.message || 'Error running simulator');
      else Alert.alert('Error', e.message || 'Error running simulator');
    }
    setSimulating(false);
  };

  const handleRetrain = async () => {
    try {
      if (Platform.OS === 'web') {
        const confirm = window.confirm("Initiate training pipeline? This will analyze the latest data and safely deploy if metrics improve.");
        if (!confirm) return;
      } else {
        // Assume native Alert logic could be here if needed, keeping simple for web/mobile hybrid
      }

      const res = await api.post('/ai/retrain', {});
      if (Platform.OS === 'web') window.alert(res.message);
      else Alert.alert('Success', res.message);
    } catch (err: any) {
      if (Platform.OS === 'web') window.alert(err.message);
      else Alert.alert('Error', err.message);
    }
  };

  useEffect(() => {
    const fetchInsights = async () => {
      try {
        const data = await api.get('/ai/insights');
        setInsights(data);
      } catch (err: any) {
        setErrorMsg(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchInsights();
  }, []);

  if (loading) {
    return (
      <View className="flex-1 bg-brand-light dark:bg-[#0F172A] items-center justify-center">
        <ActivityIndicator size="large" color="#F97316" />
        <Text className="mt-4 text-brand-text dark:text-white font-semibold">Loading ML Insights...</Text>
      </View>
    );
  }

  if (errorMsg) {
    return (
      <View className="flex-1 bg-brand-light dark:bg-[#0F172A] items-center justify-center p-8">
        <Ionicons name="alert-circle" size={48} color="#EF4444" />
        <Text className="mt-4 text-brand-text dark:text-white font-bold text-lg text-center">Failed to load insights</Text>
        <Text className="mt-2 text-gray-500 dark:text-gray-400 text-center">{errorMsg}</Text>
        <Text className="mt-4 text-gray-400 dark:text-gray-500 text-xs text-center">Ensure the Python FastAPI backend is running.</Text>
      </View>
    );
  }

  return (
    <View className="flex-1 bg-brand-light dark:bg-[#0F172A]">
      <TopNav title="AI Analytics & Insights" showAction={false} />
      <ScrollView showsVerticalScrollIndicator={false} className={isMobile ? "p-4" : "p-8"}>
        <View className="mb-8 flex-row justify-between items-start">
          <View className="flex-1">
            <Text className="text-3xl font-bold text-brand-text dark:text-white mb-2">ML Insights</Text>
            <Text className="text-gray-500 dark:text-gray-400">
              Live model analytics from your project and construction data. Cost predictions and delay risks are machine-learning estimates — not financial commitments.
            </Text>
          </View>
          <Pressable 
            className="bg-brand-orange px-4 py-2 rounded-lg flex-row items-center ml-4"
            onPress={handleRetrain}
          >
            <Ionicons name="refresh-outline" size={16} color="#fff" />
            <Text className="text-white font-bold ml-2">Retrain Model</Text>
          </Pressable>
        </View>

        {/* Model Performance Overview */}
        <View style={{ flexDirection: isMobile ? 'column' : 'row', gap: 16, marginBottom: 24 }}>
          <View className="flex-1 bg-white dark:bg-[#1E293B] p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-800 flex-row items-center">
            <View className="w-12 h-12 rounded-full bg-blue-50 dark:bg-gray-800 items-center justify-center mr-4">
              <Ionicons name="server-outline" size={24} color="#3B82F6" />
            </View>
            <View>
              <Text className="text-gray-500 dark:text-gray-400 font-semibold text-sm">Active Model</Text>
              <Text className="text-brand-text dark:text-white font-bold text-base mt-1">{insights?.active_model}</Text>
            </View>
          </View>

          <View className="flex-1 bg-white dark:bg-[#1E293B] p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-800 flex-row items-center">
            <View className="w-12 h-12 rounded-full bg-green-50 dark:bg-gray-800 items-center justify-center mr-4">
              <Ionicons name="analytics-outline" size={24} color="#10B981" />
            </View>
            <View>
              <Text className="text-gray-500 dark:text-gray-400 font-semibold text-sm">R² Score (Cost Model)</Text>
              <Text className="text-brand-text dark:text-white font-bold text-base mt-1">
                {insights?.accuracy_score != null && insights.accuracy_score !== 'Not validated'
                  ? `${insights.accuracy_score} / 1.0`
                  : 'Not validated'}
              </Text>
            </View>
          </View>

          <View className="flex-1 bg-white dark:bg-[#1E293B] p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-800 flex-row items-center">
            <View className="w-12 h-12 rounded-full bg-purple-50 dark:bg-gray-800 items-center justify-center mr-4">
              <Ionicons name="documents-outline" size={24} color="#8B5CF6" />
            </View>
            <View>
              <Text className="text-gray-500 dark:text-gray-400 font-semibold text-sm">Training Samples</Text>
              <Text className="text-brand-text dark:text-white font-bold text-base mt-1">
                {insights?.total_training_samples?.toLocaleString() ?? '—'}
              </Text>
            </View>
          </View>

          <View className="flex-1 bg-white dark:bg-[#1E293B] p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-800 flex-row items-center">
            <View className="w-12 h-12 rounded-full bg-orange-50 dark:bg-gray-800 items-center justify-center mr-4">
              <Ionicons name="calendar-outline" size={24} color="#F97316" />
            </View>
            <View>
              <Text className="text-gray-500 dark:text-gray-400 font-semibold text-sm">Last Trained</Text>
              <Text className="text-brand-text dark:text-white font-bold text-base mt-1">
                {insights?.model_info?.cost_model?.trained_at
                  ? new Date(insights.model_info.cost_model.trained_at).toLocaleDateString()
                  : '—'}
              </Text>
            </View>
          </View>
        </View>

        <View style={{ flexDirection: isMobile ? 'column' : 'row', gap: 24, marginBottom: 32 }}>
          {/* Feature importance data from the insights endpoint */}
          <View style={{ flex: isMobile ? undefined : 3, width: isMobile ? '100%' : undefined, backgroundColor: '#fff', borderRadius: 16, padding: isMobile ? 16 : 28, borderWidth: 1, borderColor: '#F3F4F6' }}>
            <Text className="text-lg font-bold text-brand-text dark:text-white mb-1">Cost Driver Analysis</Text>
            <Text className="text-gray-400 text-xs mb-6">
              Global feature importance from the RandomForest cost model — how much each input variable influenced the training set's cost predictions overall.
            </Text>

            <View className="gap-5">
              {insights?.feature_importance?.length > 0 ? insights.feature_importance.map((feature: any, index: number) => (
                <View key={index}>
                  <View className="flex-row justify-between mb-2">
                    <Text className="font-semibold text-gray-700 dark:text-gray-300">{feature.name}</Text>
                    <Text className="font-bold text-brand-orange">{feature.value}%</Text>
                  </View>
                  <View className="w-full bg-gray-100 dark:bg-gray-800 h-3 rounded-full overflow-hidden">
                    <View className="bg-brand-orange h-full rounded-full" style={{ width: `${feature.value}%` }} />
                  </View>
                </View>
              )) : <Text className="text-gray-400 dark:text-gray-500 italic">No feature importance data. Run the training pipeline first.</Text>}
            </View>
            <Text className="text-xs text-gray-400 dark:text-gray-500 mt-6 italic">
              Trained on {insights?.total_training_samples?.toLocaleString() ?? 'unknown'} records · Last updated {insights?.model_info?.cost_model?.trained_at ? new Date(insights.model_info.cost_model.trained_at).toLocaleDateString() : 'unknown'}
            </Text>
          </View>

          {/* Delay Risk per Project */}
          <View style={{ flex: isMobile ? undefined : 2, width: isMobile ? '100%' : undefined, gap: 16 }}>
            <View className="bg-white dark:bg-[#1E293B] p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-800">
              <Text className="text-lg font-bold text-brand-text dark:text-white mb-1">Delay Risk by Project</Text>
              <Text className="text-gray-400 text-xs mb-4">
                Risk % computed from overdue milestones + late purchase orders for each project.
              </Text>
              {(insights?.projects?.length ?? 0) === 0 ? (
                <Text className="text-gray-400 italic text-sm">No active projects to assess.</Text>
              ) : (
                insights.projects.slice(0, 5).map((proj: any) => {
                  const risk = proj.delay_risk ?? 0;
                  const color = risk > 70 ? '#EF4444' : risk > 40 ? '#F97316' : '#22C55E';
                  return (
                    <Pressable 
                      key={proj.project_id} 
                      className="mb-4 bg-gray-50 dark:bg-gray-800/50 p-3 rounded-lg"
                      onPress={() => router.push(`/admin/projects/${proj.project_id}`)}
                    >
                      <View className="flex-row justify-between mb-1">
                        <Text className="text-sm font-semibold text-gray-700 dark:text-gray-300 flex-1 mr-2" numberOfLines={1}>
                          {proj.project_name}
                        </Text>
                        <Text className="text-sm font-bold" style={{ color }}>{risk}%</Text>
                      </View>
                      <View className="w-full h-2 bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden mb-2">
                        <View style={{ width: `${Math.min(risk, 100)}%`, height: '100%', backgroundColor: color, borderRadius: 4 }} />
                      </View>
                      <Text className="text-gray-500 dark:text-gray-400 text-xs mb-1">
                        {proj.recommendation}
                      </Text>
                      <View className="flex-row items-center mt-2 flex-wrap gap-2">
                        {proj.milestone_overdue_count > 0 && <View className="bg-red-100 px-2 py-1 rounded text-xs"><Text className="text-red-700 text-[10px] font-bold uppercase">{proj.milestone_overdue_count} Milestones Overdue</Text></View>}
                        {proj.late_po_count > 0 && <View className="bg-orange-100 px-2 py-1 rounded text-xs"><Text className="text-orange-700 text-[10px] font-bold uppercase">{proj.late_po_count} Late POs</Text></View>}
                        {proj.is_over_budget && <View className="bg-purple-100 px-2 py-1 rounded text-xs"><Text className="text-purple-700 text-[10px] font-bold uppercase">Over Budget</Text></View>}
                        {proj.attendance_gap > 0 && <View className="bg-yellow-100 px-2 py-1 rounded text-xs"><Text className="text-yellow-700 text-[10px] font-bold uppercase">Low Attendance</Text></View>}
                      </View>
                    </Pressable>
                  );
                })
              )}
            </View>

            <View className="bg-white dark:bg-[#1E293B] p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-800">
              <Text className="text-lg font-bold text-brand-text dark:text-white mb-4">Project Health Overview</Text>
              <View className="gap-4">
                <View className="flex-row justify-between items-center">
                  <Text className="text-gray-500 dark:text-gray-400 font-semibold">Total Projects</Text>
                  <Text className="font-bold text-brand-text dark:text-white text-lg">{insights?.project_health?.total || 0}</Text>
                </View>
                <View className="flex-row justify-between items-center">
                  <Text className="text-gray-500 dark:text-gray-400 font-semibold">Active In-Progress</Text>
                  <Text className="font-bold text-blue-500 text-lg">{insights?.project_health?.active || 0}</Text>
                </View>
                <View className="flex-row justify-between items-center">
                  <Text className="text-gray-500 dark:text-gray-400 font-semibold">Completed</Text>
                  <Text className="font-bold text-green-500 text-lg">{insights?.project_health?.completed || 0}</Text>
                </View>
                {(insights?.project_health?.trending_over_budget || 0) > 0 && (
                  <View className="flex-row justify-between items-center bg-red-50 p-2 rounded-lg mt-2">
                    <Text className="text-red-700 font-semibold text-xs">Trending Over Budget</Text>
                    <Text className="font-bold text-red-700 text-sm">{insights.project_health.trending_over_budget}</Text>
                  </View>
                )}
                <View className="mt-4 pt-4 border-t border-gray-100 dark:border-gray-800">
                  <Text className="text-xs text-gray-400 dark:text-gray-500 font-bold uppercase tracking-wider mb-2">Budget Compliance</Text>
                  <View className="flex-row items-end">
                    <Text className="text-3xl font-black text-brand-text dark:text-white leading-none">{insights?.project_health?.on_budget_percent || 0}%</Text>
                    <Text className="text-sm text-gray-400 font-semibold ml-2 mb-1">On Budget</Text>
                  </View>
                </View>
              </View>
            </View>
          </View>
        </View>

        <View className="bg-white dark:bg-[#1E293B] p-8 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-800 mb-8">
            <Text className="text-lg font-bold text-brand-text dark:text-white mb-2">Market Trends (Avg Cost / SqFt)</Text>
            <Text className="text-gray-400 text-xs mb-6">Real benchmarks calculated from completed projects, grouped by location and type.</Text>
            
            <View className="flex-row flex-wrap gap-4">
              {!insights?.market_trends?.length ? (
                 <Text className="text-gray-500 italic">Need at least 1 completed project with valid cost and sqft data to show market trends. Currently have 0.</Text>
              ) : (
                insights.market_trends.map((trend: any, index: number) => (
                  <View key={index} className="flex-1 min-w-[150px] p-4 rounded-xl bg-gray-50 dark:bg-[#0F172A] border border-gray-100 dark:border-gray-800">
                    <Text className="font-bold text-gray-500 dark:text-gray-400 mb-1">{trend.location} — {trend.project_type}</Text>
                    <Text className="font-black text-brand-text dark:text-white text-lg mb-2">
                      LKR {trend.avg_cost_per_sqft.toLocaleString(undefined, {maximumFractionDigits: 0})} / sqft
                    </Text>
                    <View className="bg-blue-100 self-start px-2 py-1 rounded">
                      <Text className="text-blue-700 text-[10px] font-bold uppercase">Based on {trend.sample_size} Project{trend.sample_size > 1 ? 's' : ''}</Text>
                    </View>
                  </View>
                ))
              )}
            </View>
        </View>

        {/* What-If Simulator */}
        <View className="bg-white dark:bg-[#1E293B] p-8 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-800 mb-12">
            <Text className="text-lg font-bold text-brand-text dark:text-white mb-2">Cost Simulator (What-If Analysis)</Text>
            <Text className="text-gray-400 text-xs mb-6">Adjust parameters to see how the model's cost prediction shifts in real time.</Text>
            
            <View className="flex-row flex-wrap items-end gap-4">
              <View className="flex-1 min-w-[200px]">
                <Text className="text-sm font-semibold text-gray-700 mb-2">Square Footage</Text>
                <TextInput 
                  value={simSqft}
                  onChangeText={setSimSqft}
                  className="bg-gray-50 border border-gray-200 rounded-lg p-3 text-brand-text"
                  keyboardType="numeric"
                />
              </View>
              <View className="flex-1 min-w-[200px]">
                <Text className="text-sm font-semibold text-gray-700 mb-2">Quality Tier</Text>
                <View className="flex-row bg-gray-50 rounded-lg border border-gray-200 p-1">
                  {['Standard', 'Premium', 'Luxury'].map(q => (
                    <Pressable 
                      key={q} 
                      onPress={() => setSimQuality(q)}
                      className={`flex-1 items-center py-2 rounded-md ${simQuality === q ? 'bg-white shadow-sm' : ''}`}
                    >
                      <Text className={`text-sm font-bold ${simQuality === q ? 'text-brand-orange' : 'text-gray-500'}`}>{q}</Text>
                    </Pressable>
                  ))}
                </View>
              </View>
              
              <Pressable 
                onPress={runSimulator}
                disabled={simulating}
                className={`bg-brand-orange px-8 py-3 rounded-lg h-[46px] justify-center ${simulating ? 'opacity-50' : ''}`}
              >
                {simulating ? <ActivityIndicator color="#fff" /> : <Text className="text-white font-bold">Simulate</Text>}
              </Pressable>
            </View>

            {simResult !== null && (
              <View className="mt-6 p-6 bg-orange-50 border border-orange-100 rounded-xl flex-row items-center justify-between">
                <View>
                  <Text className="text-gray-600 font-semibold mb-1">Simulated Total Cost</Text>
                  <Text className="text-3xl font-black text-brand-text">LKR {simResult.toLocaleString(undefined, {maximumFractionDigits:0})}</Text>
                </View>
                <Ionicons name="calculator-outline" size={32} color="#F97316" className="opacity-50" />
              </View>
            )}
        </View>

      </ScrollView>
    </View>
  );
}

import { ModalViewport } from '@/components/common/ModalViewport';
import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, ActivityIndicator, Pressable, Alert, Platform } from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { supabase } from '../../../../lib/supabase';
import { TopNav } from '@/components/common/TopNav';
import { Ionicons, FontAwesome5 } from '@expo/vector-icons';
import { format } from 'date-fns';
import { api } from '../../../../services/api';
import { ChatWidget } from '../../../../components/shared/ChatWidget';
import { Modal, TextInput } from 'react-native';

const SuggestModal = ({ visible, order, onClose, onSubmit }: any) => {
  const [qty, setQty] = useState('');
  const [date, setDate] = useState('');
  const [price, setPrice] = useState('');
  const [notes, setNotes] = useState('');

  useEffect(() => {
    if (order) {
      setQty((order.suggested_quantity || order.quantity_ordered)?.toString() || '');
      setDate(order.suggested_date || order.expected_date || '');
      setPrice(order.suggested_price ? order.suggested_price.toString() : (order.unit_price ? order.unit_price.toString() : ''));
      setNotes('');
    }
  }, [order]);

  if (!visible || !order) return null;

  return (
    <Modal visible={visible} transparent animationType="fade" onRequestClose={onClose}>
      <ModalViewport>
        <ScrollView keyboardShouldPersistTaps="handled" nestedScrollEnabled style={{ flexGrow: 0, flexShrink: 1 }} contentContainerStyle={{ padding: 24 }} className="bg-white rounded-2xl w-full max-w-md max-h-full">
          <Text className="text-xl font-bold text-brand-text mb-4">Counter-Offer</Text>
          <Text className="text-gray-500 mb-4 text-sm">Propose a different quantity, date, or price to the supplier.</Text>

          <Text className="font-semibold text-gray-700 mb-1">Suggested Quantity</Text>
          <TextInput 
            className="border border-gray-300 rounded-lg p-3 mb-4 text-brand-text"
            keyboardType="numeric"
            value={qty}
            onChangeText={setQty}
          />

          <Text className="font-semibold text-gray-700 mb-1">Suggested Date (YYYY-MM-DD)</Text>
          <TextInput 
            className="border border-gray-300 rounded-lg p-3 mb-4 text-brand-text"
            value={date}
            onChangeText={setDate}
          />

          <Text className="font-semibold text-gray-700 mb-1">Suggested Unit Price (LKR)</Text>
          <TextInput 
            className="border border-gray-300 rounded-lg p-3 mb-4 text-brand-text"
            keyboardType="numeric"
            value={price}
            onChangeText={setPrice}
          />

          <Text className="font-semibold text-gray-700 mb-1">Notes to Supplier</Text>
          <TextInput 
            className="border border-gray-300 rounded-lg p-3 mb-6 text-brand-text h-20"
            multiline
            value={notes}
            onChangeText={setNotes}
          />

          <View className="flex-row justify-end space-x-3">
            <Pressable onPress={onClose} className="px-4 py-2">
              <Text className="text-gray-500 font-bold">Cancel</Text>
            </Pressable>
            <Pressable 
              onPress={() => onSubmit(order.id, parseFloat(qty), date, parseFloat(price), notes)} 
              className="bg-brand-warning px-6 py-2 rounded-lg"
            >
              <Text className="text-white font-bold">Submit Counter</Text>
            </Pressable>
          </View>
        </ScrollView>
      </ModalViewport>
    </Modal>
  );
};


export default function AdminMaterialsOrdersIdPage() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const router = useRouter();

  const [order, setOrder] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState(false);
  const [suggestModalVisible, setSuggestModalVisible] = useState(false);
  const [assignModalVisible, setAssignModalVisible] = useState(false);
  const [projects, setProjects] = useState<any[]>([]);
  const [currentUserId, setCurrentUserId] = useState('');

  useEffect(() => { 
    supabase.auth.getSession().then(({data}) => setCurrentUserId(data.session?.user.id || '')); 
    supabase.from('projects').select('id, name').then(({data}) => setProjects(data || []));
  }, []);

  const fetchOrder = async () => {
    try {
      const { data, error } = await supabase
        .from('purchase_orders')
        .select(`
          *,
          project:projects(name)
        `)
        .eq('id', id)
        .single();
        
      if (error) throw error;
      setOrder(data);
    } catch (err: any) {
      if (Platform.OS === 'web') console.error(err);
      else Alert.alert('Error', 'Failed to fetch order details');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOrder();
  }, [id]);

  const handleUpdateStatus = async (newStatus: 'Confirmed' | 'Rejected' | 'Delivered' | 'Received') => {
    const proceed = await new Promise((resolve) => {
      Alert.alert(
        'Confirm Action',
        `Are you sure you want to mark this order as ${newStatus}?`,
        [
          { text: 'Cancel', style: 'cancel', onPress: () => resolve(false) },
          { text: 'Yes', onPress: () => resolve(true) }
        ]
      );
    });
    if (!proceed) return;

    setActionLoading(true);
    try {
      if (!id) throw new Error('Order id is required');
      if (newStatus === 'Confirmed') await api.purchaseOrders.approve(id);
      if (newStatus === 'Rejected') await api.purchaseOrders.reject(id);
      if (newStatus === 'Delivered') await api.purchaseOrders.deliver(id);
      if (newStatus === 'Received') await api.purchaseOrders.receive(id);
      
      if (Platform.OS === 'web') window.alert(`Order marked as ${newStatus}!`);
      else Alert.alert('Success', `Order marked as ${newStatus}!`);
      
      // Refresh data
      fetchOrder();
    } catch (err: any) {
      if (Platform.OS === 'web') window.alert('Failed to update status');
      else Alert.alert('Error', 'Failed to update status');
    } finally {
      setActionLoading(false);
    }
  };

  const handleSuggestSubmit = async (orderId: string, qty: number, date: string, price: number, notes: string) => {
    try {
      setActionLoading(true);
      setSuggestModalVisible(false);
      await api.purchaseOrders.suggest(orderId, {
        suggested_quantity: qty,
        suggested_date: date,
        suggested_price: price,
        supplier_notes: notes
      });
      fetchOrder();
    } catch (e: any) {
      Alert.alert('Error', 'Failed to submit suggestion');
    } finally {
      setActionLoading(false);
    }
  };

  const handleAssignProject = async (projectId: string) => {
    try {
      setActionLoading(true);
      const { error } = await supabase.from('purchase_orders').update({ project_id: projectId }).eq('id', id);
      if (error) throw error;
      setAssignModalVisible(false);
      fetchOrder();
      Alert.alert('Success', 'Project assigned successfully.');
    } catch (e: any) {
      Alert.alert('Error', e.message || 'Failed to assign project');
    } finally {
      setActionLoading(false);
    }
  };

  if (loading) {
    return (
      <View className="flex-1 bg-brand-light items-center justify-center">
        <ActivityIndicator size="large" color="#F97316" />
      </View>
    );
  }

  if (!order) {
    return (
      <View className="flex-1 bg-brand-light">
        <TopNav title="Order Not Found" showAction={false} />
        <View className="flex-1 items-center justify-center">
          <Text className="text-gray-500">The requested order could not be found.</Text>
          <Pressable onPress={() => router.back()} className="mt-4 bg-brand-orange px-6 py-2 rounded-lg">
            <Text className="text-white font-bold">Go Back</Text>
          </Pressable>
        </View>
      </View>
    );
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Delivered': return 'bg-green-100 text-green-700 border-green-200';
      case 'Pending Delivery': return 'bg-orange-100 text-orange-700 border-orange-200';
      case 'Confirmed': return 'bg-blue-100 text-blue-700 border-blue-200';
      case 'Rejected': case 'Cancelled': return 'bg-red-100 text-red-700 border-red-200';
      default: return 'bg-gray-100 text-gray-700 border-gray-200';
    }
  };

  const isCompleted = order.status === 'Received' || order.status === 'Rejected' || order.status === 'Cancelled';

  // Parse negotiation log
  let negotiationLog: any[] = [];
  try {
    if (order.supplier_notes) {
      const parsed = JSON.parse(order.supplier_notes);
      if (Array.isArray(parsed)) {
        negotiationLog = parsed;
      }
    }
  } catch (e) {}

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav title={`Order ${order.po_number}`} showAction={false} />
      
      <ScrollView className="flex-1 p-6" showsVerticalScrollIndicator={false}>
        <View className="max-w-[700px] w-full mx-auto">
          
          <Pressable onPress={() => router.back()} className="flex-row items-center mb-6 self-start">
            <Ionicons name="arrow-back" size={20} color="#6B7280" />
            <Text className="text-gray-500 font-semibold ml-2">Back to Orders</Text>
          </Pressable>

          {/* Main Details Card */}
          <View className="bg-white rounded-2xl shadow-sm border border-gray-100 p-8 mb-6">
            <View className="flex-row justify-between items-start mb-8 pb-6 border-b border-gray-100">
              <View>
                <Text className="text-3xl font-bold text-gray-800 mb-2">{order.po_number}</Text>
                <Text className="text-gray-500 flex-row items-center">
                  <Ionicons name="calendar-outline" size={14} /> Created on {format(new Date(order.created_at), 'MMM dd, yyyy')}
                </Text>
              </View>
              <View className={`px-4 py-2 rounded-lg border ${getStatusColor(order.status)}`}>
                <Text className="font-bold uppercase tracking-wide text-xs">{order.status}</Text>
              </View>
            </View>

            <View className="flex-row flex-wrap mb-8">
              <View className="w-1/2 mb-6">
                <Text className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-1">Supplier</Text>
                <View className="flex-row items-center">
                  <View className="w-8 h-8 rounded-full bg-blue-50 items-center justify-center mr-3">
                    <FontAwesome5 name="truck" size={12} color="#3B82F6" />
                  </View>
                  <Text className="text-gray-800 font-medium text-base">{order.supplier_name || 'Unknown'}</Text>
                </View>
              </View>

              <View className="w-1/2 mb-6">
                <Text className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-1">Project Site</Text>
                <View className="flex-row items-center">
                  <View className="w-8 h-8 rounded-full bg-emerald-50 items-center justify-center mr-3">
                    <FontAwesome5 name="hard-hat" size={12} color="#10B981" />
                  </View>
                  <Text className="text-gray-800 font-medium text-base mr-2">{order.project?.name || 'Unassigned'}</Text>
                  {!order.project && (
                    <Pressable onPress={() => setAssignModalVisible(true)} className="bg-gray-200 px-3 py-1 rounded-full">
                      <Text className="text-xs text-gray-700 font-bold">Assign</Text>
                    </Pressable>
                  )}
                </View>
              </View>

              <View className="w-1/2">
                <Text className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-1">Expected Delivery</Text>
                <Text className="text-gray-800 font-medium text-base">
                  {order.expected_date ? format(new Date(order.expected_date), 'MMM dd, yyyy') : 'TBD'}
                </Text>
              </View>

              <View className="w-1/2">
                <Text className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-1">Total Cost</Text>
                <Text className="text-brand-orange font-bold text-xl">
                  Rs. {(order.total_price || 0).toLocaleString()}
                </Text>
              </View>
            </View>

            {/* Items Ordered Section */}
            <View className="bg-gray-50 rounded-xl p-6 border border-gray-100">
              <Text className="text-sm font-bold text-gray-700 mb-4 uppercase tracking-wider">Items Ordered</Text>
              <View className="flex-row justify-between items-center py-3 border-b border-gray-200 mb-2">
                <Text className="text-gray-800 font-medium flex-1">{order.items}</Text>
                <Text className="text-gray-500 w-24 text-right">Qty: {order.quantity_ordered}</Text>
                <Text className="text-gray-800 font-bold w-32 text-right">Rs. {(order.unit_price || 0).toLocaleString()}</Text>
              </View>
              <View className="flex-row justify-between items-center pt-2">
                <Text className="text-gray-500 font-bold">Total</Text>
                <Text className="text-brand-orange font-bold text-lg">Rs. {(order.total_price || 0).toLocaleString()}</Text>
              </View>
            </View>

            {negotiationLog.length > 0 && (
              <View className="mt-8">
                <Text className="text-lg font-bold text-gray-800 mb-4">Negotiation History</Text>
                <View className="border-l-2 border-gray-200 ml-3 pl-4">
                  {negotiationLog.map((event, idx) => (
                    <View key={idx} className="mb-4 relative">
                      <View className={`absolute -left-6 w-4 h-4 rounded-full ${event.role === 'supplier' ? 'bg-blue-500' : 'bg-green-500'} border-4 border-white`} />
                      <Text className="text-xs text-gray-400 mb-1">{event.timestamp ? format(new Date(event.timestamp), 'MMM dd, yyyy h:mm a') : ''} • {event.role === 'supplier' ? 'Supplier' : 'You'}</Text>
                      <View className="bg-gray-50 p-3 rounded-lg border border-gray-100">
                        <Text className="font-bold text-gray-700 capitalize mb-1">{event.action}</Text>
                        {event.quantity && <Text className="text-sm text-gray-600">Qty: {event.quantity}</Text>}
                        {event.suggested_quantity && <Text className="text-sm text-gray-600">Qty: {event.suggested_quantity}</Text>}
                        {event.unit_price && <Text className="text-sm text-gray-600">Price: Rs. {event.unit_price}</Text>}
                        {event.suggested_price && <Text className="text-sm text-gray-600">Price: Rs. {event.suggested_price}</Text>}
                        {event.date && <Text className="text-sm text-gray-600">Date: {event.date}</Text>}
                        {event.suggested_date && <Text className="text-sm text-gray-600">Date: {event.suggested_date}</Text>}
                        {event.note && <Text className="text-sm text-gray-500 italic mt-2">"{event.note}"</Text>}
                      </View>
                    </View>
                  ))}
                </View>
              </View>
            )}

          </View>

          {/* Action Buttons Section */}
          {!isCompleted && (
            <View className="bg-white rounded-2xl shadow-sm border border-gray-100 p-8 flex-row justify-between items-center">
              <View className="flex-1 mr-4">
                <Text className="text-lg font-bold text-gray-800 mb-1">Update Order Status</Text>
                <Text className="text-gray-500 text-sm">Review the details above before confirming or rejecting this order.</Text>
              </View>
              
              <View className="flex-row gap-3">
                {order.status === 'Delivered' ? <Pressable
                  disabled={actionLoading}
                  onPress={() => handleUpdateStatus('Received')}
                  className="bg-brand-success px-6 py-3 rounded-lg"
                >
                  <Text className="text-white font-bold">Confirm Receipt</Text>
                </Pressable> : <Pressable
                  disabled={actionLoading}
                  onPress={() => handleUpdateStatus('Rejected')}
                  className="bg-red-50 border border-red-200 px-6 py-3 rounded-lg"
                >
                  <Text className="text-red-600 font-bold">Reject Order</Text>
                </Pressable>}
                
                {order.status === 'Suggested' ? (
                  <>
                    <Pressable
                      disabled={actionLoading}
                      onPress={() => setSuggestModalVisible(true)}
                      className="bg-yellow-500 shadow-sm px-6 py-3 rounded-lg flex-row items-center"
                    >
                      <Text className="text-white font-bold">Counter Supplier</Text>
                    </Pressable>
                    <Pressable
                      disabled={actionLoading}
                      onPress={() => handleUpdateStatus('Confirmed')}
                      className="bg-brand-success shadow-sm px-6 py-3 rounded-lg flex-row items-center"
                    >
                      {actionLoading && <ActivityIndicator size="small" color="white" className="mr-2" />}
                      <Text className="text-white font-bold">Accept Counter</Text>
                    </Pressable>
                  </>
                ) : null}
              </View>
            </View>
          )}

        </View>
      </ScrollView>

      <SuggestModal 
        visible={suggestModalVisible}
        order={order}
        onClose={() => setSuggestModalVisible(false)}
        onSubmit={handleSuggestSubmit}
      />
      
      <Modal visible={assignModalVisible} transparent animationType="fade" onRequestClose={() => setAssignModalVisible(false)}>
        <ModalViewport>
          <ScrollView keyboardShouldPersistTaps="handled" nestedScrollEnabled style={{ flexGrow: 0, flexShrink: 1 }} contentContainerStyle={{ padding: 24 }} className="bg-white rounded-2xl w-full max-w-md max-h-full">
            <Text className="text-xl font-bold text-gray-800 mb-4">Assign Project</Text>
            <Text className="text-gray-500 mb-4">Select a project for this unassigned order:</Text>
            <ScrollView className="max-h-60 mb-4">
              {projects.map(p => (
                <Pressable 
                  key={p.id} 
                  onPress={() => handleAssignProject(p.id)}
                  className="py-3 border-b border-gray-100"
                >
                  <Text className="text-gray-800">{p.name}</Text>
                </Pressable>
              ))}
            </ScrollView>
            <Pressable onPress={() => setAssignModalVisible(false)} className="self-end px-4 py-2 bg-gray-200 rounded-lg">
              <Text className="text-gray-700 font-bold">Cancel</Text>
            </Pressable>
          </ScrollView>
        </ModalViewport>
      </Modal>
    </View>
  );
}

import React, { useState, useEffect } from 'react';
import { View, Text, ScrollView, TextInput, Pressable, ActivityIndicator, Alert, Platform } from 'react-native';
import { useRouter } from 'expo-router';
import { TopNav } from '@/components/common/TopNav';
import { supabase } from '@/lib/supabase';
import { Ionicons } from '@expo/vector-icons';
import { sendSystemNotification } from '../../../../utils/notifications';
import { ProjectAssignmentDropdown } from '../../../../components/common/ProjectAssignmentDropdown';

export default function AdminMaterialsOrdersCreatePage() {
  const router = useRouter();

  const [loading, setLoading] = useState(false);
  const [initialLoading, setInitialLoading] = useState(true);

  // Data arrays
  const [suppliers, setSuppliers] = useState<any[]>([]);
  const [projects, setProjects] = useState<any[]>([]);
  const [materials, setMaterials] = useState<any[]>([]);
  const [assignments, setAssignments] = useState<any[]>([]);

  // Selected values
  const [selectedSupplier, setSelectedSupplier] = useState<any>(null);
  const [selectedProject, setSelectedProject] = useState<any>(null);
  const [selectedMaterial, setSelectedMaterial] = useState<any>(null);
  const [materialQuery, setMaterialQuery] = useState('');
  const [selectedUnit, setSelectedUnit] = useState<string>('Units');

  // Form Inputs
  const [quantity, setQuantity] = useState('');
  const [expectedDate, setExpectedDate] = useState(new Date().toISOString().split('T')[0]);

  // Dropdown states
  const [showSupplierDrop, setShowSupplierDrop] = useState(false);
  const [showProjectDrop, setShowProjectDrop] = useState(false);
  const [showMaterialDrop, setShowMaterialDrop] = useState(false);
  const [showUnitDrop, setShowUnitDrop] = useState(false);

  useEffect(() => {
    let isMounted = true;
    const fetchData = async () => {
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        const currentUserId = sessionData.session?.user.id;
        const { data: currentProfile } = currentUserId
          ? await supabase.from('profiles').select('role').eq('id', currentUserId).maybeSingle()
          : { data: null };

        // Fetch Suppliers
        const { data: supData, error: supErr } = await supabase
          .from('profiles')
          .select('id, full_name, email')
          .eq('role', 'supplier')
          .order('full_name');
        if (supErr) throw supErr;

        // Fetch Projects
        let projectQuery = supabase
          .from('projects')
          .select('id, name')
          .order('name');
        if (currentProfile?.role === 'pm' && currentUserId) {
          projectQuery = projectQuery.eq('pm_id', currentUserId);
        }
        const { data: projData, error: projErr } = await projectQuery;
        if (projErr) throw projErr;

        // Fetch Materials
        const { data: matData, error: matErr } = await supabase
          .from('materials')
          .select('id, name')
          .order('name');
        
        // If materials fetch fails (e.g. RLS or table doesn't exist), just ignore
        const validMaterials = matErr ? [] : (matData || []);

        // Fetch Assignments
        const { data: assignData } = await supabase
          .from('project_role_assignments')
          .select('project_id, user_id')
          .eq('role', 'supplier');

        if (isMounted) {
          setSuppliers(supData || []);
          setProjects(projData || []);
          setMaterials(validMaterials);
          setAssignments(assignData || []);
        }
      } catch (err: any) {
        if (isMounted && Platform.OS !== 'web') {
          Alert.alert('Error loading data', err.message);
        } else if (isMounted && Platform.OS === 'web') {
          console.error('Error loading data', err.message);
        }
      } finally {
        if (isMounted) setInitialLoading(false);
      }
    };

    fetchData();
    return () => { isMounted = false; };
  }, []);

  
  const handleCreateMaterial = async () => {
    try {
      const { data, error } = await supabase.from('materials').insert([{ name: materialQuery }]).select().single();
      if (error) throw error;
      setMaterials([...materials, data].sort((a, b) => a.name.localeCompare(b.name)));
      setSelectedMaterial(data);
      setMaterialQuery(data.name);
      setShowMaterialDrop(false);
    } catch (err: any) {
      if (Platform.OS === 'web') window.alert(err.message);
      else Alert.alert('Error', err.message);
    }
  };

  const handleAssignSuppliers = async (newSupplierIds: string[]) => {
    if (!selectedProject || newSupplierIds.length === 0) return;
    try {
      setLoading(true);
      const inserts = newSupplierIds.map(id => ({
        project_id: selectedProject.id,
        user_id: id,
        role: 'supplier'
      }));
      const { error } = await supabase.from('project_role_assignments').insert(inserts);
      if (error) throw error;
      
      const newAssignments = [...assignments, ...inserts];
      setAssignments(newAssignments);
      Alert.alert('Success', 'Suppliers assigned to project!');
    } catch (err: any) {
      Alert.alert('Error', err.message || 'Failed to assign suppliers');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async () => {
    if (!selectedSupplier || !selectedProject || !quantity) {
      const msg = 'Please select a supplier, project, and quantity.';
      if (Platform.OS === 'web') window.alert(msg);
      else Alert.alert('Error', msg);
      return;
    }

    setLoading(true);
    try {
      // Generate a random PO Number
      const poNumber = `PO-${Math.random().toString(36).substring(2, 10).toUpperCase()}`;
      
      const q = parseFloat(quantity);

      // Construct items string
      const itemsString = selectedMaterial 
        ? `${q} ${selectedUnit} of ${selectedMaterial.name}`
        : `${q} ${selectedUnit} of Material`;

      const orderData: any = {
        project_id: selectedProject.id,
        supplier_id: selectedSupplier.id,
        supplier_name: selectedSupplier.full_name,
        quantity_ordered: q,
        unit_price: 0,
        total_price: 0,
        po_number: poNumber,
        items: itemsString,
        expected_date: expectedDate,
        status: 'Pending Delivery'
      };

      if (selectedMaterial) {
        orderData.material_id = selectedMaterial.id;
      }

      const { error } = await supabase.from('purchase_orders').insert([orderData]);
      if (error) throw error;
      
      // Dispatch notification
      await sendSystemNotification(
        'Purchase Order Created',
        `PO #${orderData.po_number} was created for ${selectedMaterial ? selectedMaterial.name : 'materials'}.`,
        'Supplier',
        orderData.supplier_id
      );

      if (Platform.OS === 'web') window.alert('Order created successfully!');
      else Alert.alert('Success', 'Order created successfully!');
      
      router.back();

    } catch (err: any) {
      const msg = err.message || 'Failed to create order.';
      if (Platform.OS === 'web') window.alert(msg);
      else Alert.alert('Error', msg);
    } finally {
      setLoading(false);
    }
  };

  if (initialLoading) {
    return (
      <View className="flex-1 bg-brand-light items-center justify-center">
        <ActivityIndicator size="large" color="#F97316" />
      </View>
    );
  }

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav title="Create New Order" showAction={false} />
      <ScrollView className="flex-1 p-6" showsVerticalScrollIndicator={false}>
        <View className="max-w-[600px] w-full mx-auto">

          <View className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 mb-8">
            <Text className="text-xl font-bold text-gray-800 mb-6">Order Details</Text>

            {/* Project Dropdown */}
            <Text className="text-xs font-semibold text-gray-500 uppercase mb-1">Assign to Project</Text>
            <View className="relative z-[60] mb-4">
              <Pressable 
                onPress={() => { setShowProjectDrop(!showProjectDrop); setShowSupplierDrop(false); setShowMaterialDrop(false); }}
                className="flex-row justify-between items-center border border-gray-200 rounded-lg px-4 py-3 bg-gray-50"
              >
                <Text className={selectedProject ? "text-gray-800" : "text-gray-400"}>
                  {selectedProject ? selectedProject.name : 'Select project first...'}
                </Text>
                <Ionicons name="chevron-down" size={20} color="#9CA3AF" />
              </Pressable>
              
              {showProjectDrop && (
                <View className="absolute top-full left-0 right-0 bg-white border border-gray-200 mt-1 rounded-lg shadow-lg max-h-48 z-[60]">
                  <ScrollView nestedScrollEnabled={true}>
                    {projects.length === 0 ? (
                      <Text className="p-4 text-gray-500">No projects found.</Text>
                    ) : (
                      projects.map(proj => (
                        <Pressable 
                          key={proj.id} 
                          onPress={() => { setSelectedProject(proj); setSelectedSupplier(null); setShowProjectDrop(false); }}
                          className="px-4 py-3 border-b border-gray-100 hover:bg-gray-50"
                        >
                          <Text className="text-gray-800">{proj.name}</Text>
                        </Pressable>
                      ))
                    )}
                  </ScrollView>
                </View>
              )}
            </View>

            {/* Supplier Dropdown */}
            <Text className="text-xs font-semibold text-gray-500 uppercase mb-1">Select Supplier</Text>
            
            {!selectedProject ? (
              <View className="bg-gray-50 border border-gray-200 rounded-lg px-4 py-3 mb-4">
                <Text className="text-gray-400">Please select a project first</Text>
              </View>
            ) : (() => {
              const projectSupplierIds = assignments.filter(a => a.project_id === selectedProject.id).map(a => a.user_id);
              const availableSuppliers = suppliers.filter(s => projectSupplierIds.includes(s.id));
              
              if (availableSuppliers.length === 0) {
                return (
                  <View className="bg-orange-50 border border-orange-100 p-4 rounded-lg mb-4 z-[50]">
                    <Text className="text-orange-800 font-bold mb-2">No suppliers assigned</Text>
                    <Text className="text-sm text-orange-700 mb-4">You must assign at least one supplier to {selectedProject.name} before ordering.</Text>
                    <ProjectAssignmentDropdown 
                      label="Assign Suppliers Now" 
                      users={suppliers} 
                      multiple 
                      selectedIds={[]} 
                      onChange={handleAssignSuppliers} 
                    />
                  </View>
                );
              }

              return (
                <View className="relative z-[50] mb-4">
                  <Pressable 
                    onPress={() => { setShowSupplierDrop(!showSupplierDrop); setShowProjectDrop(false); setShowMaterialDrop(false); }}
                    className="flex-row justify-between items-center border border-gray-200 rounded-lg px-4 py-3 bg-gray-50"
                  >
                    <Text className={selectedSupplier ? "text-gray-800" : "text-gray-400"}>
                      {selectedSupplier ? selectedSupplier.full_name : 'Select an assigned supplier...'}
                    </Text>
                    <Ionicons name="chevron-down" size={20} color="#9CA3AF" />
                  </Pressable>
                  
                  {showSupplierDrop && (
                    <View className="absolute top-full left-0 right-0 bg-white border border-gray-200 mt-1 rounded-lg shadow-lg max-h-48 z-[50]">
                      <ScrollView nestedScrollEnabled={true}>
                        {availableSuppliers.map(sup => (
                          <Pressable 
                            key={sup.id} 
                            onPress={() => { setSelectedSupplier(sup); setShowSupplierDrop(false); }}
                            className="px-4 py-3 border-b border-gray-100 hover:bg-gray-50"
                          >
                            <Text className="text-gray-800 font-medium">{sup.full_name}</Text>
                            <Text className="text-xs text-gray-500">{sup.email || 'No email'}</Text>
                          </Pressable>
                        ))}
                      </ScrollView>
                    </View>
                  )}
                </View>
              );
            })()}

            {/* Material Dropdown */}
            <Text className="text-xs font-semibold text-gray-500 uppercase mb-1">Material</Text>
            <View className="relative z-40 mb-4">
              <View className="flex-row justify-between items-center border border-gray-200 rounded-lg bg-gray-50 pr-4">
                <TextInput
                  className="flex-1 px-4 py-3 text-sm text-gray-800"
                  placeholder="Search or type new material..."
                  value={materialQuery}
                  onChangeText={(text) => {
                    setMaterialQuery(text);
                    setShowMaterialDrop(true);
                    setSelectedMaterial(null);
                  }}
                  onFocus={() => {
                     setShowMaterialDrop(true);
                     setShowSupplierDrop(false);
                     setShowProjectDrop(false);
                  }}
                />
                <Ionicons name="chevron-down" size={20} color="#9CA3AF" onPress={() => { setShowMaterialDrop(!showMaterialDrop); setShowSupplierDrop(false); setShowProjectDrop(false); }} />
              </View>
              
              {showMaterialDrop && (
                <View className="absolute top-full left-0 right-0 bg-white border border-gray-200 mt-1 rounded-lg shadow-lg max-h-48 z-40">
                  <ScrollView nestedScrollEnabled={true}>
                    {materials.filter(m => m.name.toLowerCase().includes(materialQuery.toLowerCase())).map(mat => (
                        <Pressable 
                          key={mat.id} 
                          onPress={() => { setSelectedMaterial(mat); setMaterialQuery(mat.name); setShowMaterialDrop(false); }}
                          className="px-4 py-3 border-b border-gray-100 hover:bg-gray-50"
                        >
                          <Text className="text-gray-800">{mat.name}</Text>
                        </Pressable>
                    ))}
                    {materialQuery.trim() !== '' && !materials.some(m => m.name.toLowerCase() === materialQuery.trim().toLowerCase()) && (
                        <Pressable 
                          onPress={handleCreateMaterial}
                          className="px-4 py-3 border-b border-gray-100 bg-orange-50 hover:bg-orange-100 flex-row items-center"
                        >
                          <Ionicons name="add-circle-outline" size={18} color="#F97316" style={{marginRight: 8}} />
                          <Text className="text-brand-orange font-bold">Create "{materialQuery}"</Text>
                        </Pressable>
                    )}
                    {materials.length === 0 && materialQuery.trim() === '' && (
                      <Text className="p-4 text-gray-500">No materials in database. Type to create one.</Text>
                    )}
                  </ScrollView>
                </View>
              )}
            </View>

            {/* Pricing & Quantities */}
            <View className="flex-row gap-4 mb-4 z-20">
              <View className="flex-[0.5]">
                <Text className="text-xs font-semibold text-gray-500 uppercase mb-1">Quantity</Text>
                <TextInput
                  className="border border-gray-200 rounded-lg px-4 py-3 text-sm text-gray-800 bg-gray-50"
                  placeholder="e.g. 100"
                  value={quantity}
                  onChangeText={setQuantity}
                  keyboardType="numeric"
                />
              </View>
              
              <View className="flex-[0.5]">
                <Text className="text-xs font-semibold text-gray-500 uppercase mb-1">Unit</Text>
                <View className="relative">
                  <Pressable 
                    onPress={() => { setShowUnitDrop(!showUnitDrop); setShowMaterialDrop(false); setShowSupplierDrop(false); setShowProjectDrop(false); }}
                    className="flex-row justify-between items-center border border-gray-200 rounded-lg px-4 py-3 bg-gray-50"
                  >
                    <Text className="text-gray-800">{selectedUnit}</Text>
                    <Ionicons name="chevron-down" size={20} color="#9CA3AF" />
                  </Pressable>
                  {showUnitDrop && (
                    <View className="absolute top-full left-0 right-0 bg-white border border-gray-200 mt-1 rounded-lg shadow-lg max-h-48 z-50">
                      <ScrollView nestedScrollEnabled={true}>
                        {['Bags', 'Cubes', 'Tons', 'Liters', 'Units', 'Pieces'].map(u => (
                          <Pressable 
                            key={u} 
                            onPress={() => { setSelectedUnit(u); setShowUnitDrop(false); }}
                            className="px-4 py-3 border-b border-gray-100 hover:bg-gray-50"
                          >
                            <Text className="text-gray-800">{u}</Text>
                          </Pressable>
                        ))}
                      </ScrollView>
                    </View>
                  )}
                </View>
              </View>
            </View>

            <Text className="text-xs font-semibold text-gray-500 uppercase mb-1">Expected Delivery Date</Text>
            <TextInput
              className="border border-gray-200 rounded-lg px-4 py-3 text-sm text-gray-800 mb-6 bg-gray-50 z-10"
              placeholder="YYYY-MM-DD"
              value={expectedDate}
              onChangeText={setExpectedDate}
            />

            {/* Submit */}
            <Pressable
              onPress={handleSubmit}
              disabled={loading}
              className="bg-brand-orange rounded-xl py-4 items-center shadow-sm z-10"
            >
              {loading
                ? <ActivityIndicator color="white" />
                : <Text className="text-white font-bold text-base">Submit Order</Text>
              }
            </Pressable>

          </View>
        </View>
      </ScrollView>
    </View>
  );
}

import React, { useEffect, useState, useCallback } from 'react';
import { View, Text, ScrollView, ActivityIndicator, Pressable, Image } from 'react-native';
import { TopNav } from '@/components/common/TopNav';
import { Ionicons } from '@expo/vector-icons';
import { useLocalSearchParams } from 'expo-router';
import { supabase } from '../../../../lib/supabase';

type SiteReport = {
  id: string;
  project_id: string;
  date: string;
  work_completed: string;
  workers_present_count: number | null;
  blockers: string | null;
  photos: string[] | null;
  created_at: string;
  site_manager?: { full_name: string; avatar_url: string | null };
};

export default function ClientProjectSiteReports() {
  const { id: projectId } = useLocalSearchParams<{ id: string }>();
  const [loading, setLoading] = useState(true);
  const [reports, setReports] = useState<SiteReport[]>([]);

  const loadData = useCallback(async () => {
    if (!projectId) return;
    try {
      setLoading(true);
      const { data: reportsData } = await supabase
        .from('site_reports')
        .select(`
          id, project_id, date, work_completed, workers_present_count, blockers, photos, created_at,
          site_manager:profiles!site_manager_id(full_name, avatar_url)
        `)
        .eq('project_id', projectId)
        .order('date', { ascending: false });
      setReports((reportsData || []) as SiteReport[]);
    } catch (error) {
      console.error('Failed to load site reports:', error);
    } finally {
      setLoading(false);
    }
  }, [projectId]);

  useEffect(() => { loadData(); }, [loadData]);

  // Realtime: refresh when a new report is submitted.
  useEffect(() => {
    if (!projectId) return;
    const channel = supabase
      .channel(`client-site-reports:${projectId}`)
      .on('postgres_changes', {
        event: 'INSERT',
        schema: 'public',
        table: 'site_reports',
        filter: `project_id=eq.${projectId}`,
      }, () => loadData())
      .subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [projectId, loadData]);

  const formatDate = (dateStr: string) =>
    new Date(dateStr).toLocaleDateString('en-LK', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric' });

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav title="Daily Site Reports" showAction={false} />

      <ScrollView className="flex-1 p-6" showsVerticalScrollIndicator={false}>
        <Text className="text-2xl font-bold text-gray-800 mb-6">Site Reports History</Text>

        {loading ? (
          <View className="py-10 items-center justify-center">
            <ActivityIndicator color="#F97316" size="large" />
          </View>
        ) : reports.length === 0 ? (
          <View className="bg-white border border-gray-100 rounded-2xl p-10 items-center justify-center">
            <Ionicons name="document-text-outline" size={48} color="#D1D5DB" />
            <Text className="text-gray-400 font-bold mt-4 text-center">No reports yet</Text>
            <Text className="text-gray-400 text-sm mt-2 text-center">Your site manager hasn't submitted any daily reports.</Text>
          </View>
        ) : (
          reports.map(report => (
            <View key={report.id} className="bg-white border border-gray-100 rounded-2xl p-6 mb-6 shadow-sm">
              <View className="flex-row justify-between items-start border-b border-gray-50 pb-4 mb-4">
                <View>
                  <Text className="text-gray-800 font-bold text-lg">{formatDate(report.date)}</Text>
                  {report.site_manager && (
                    <Text className="text-gray-500 mt-1 text-xs">Submitted by: {report.site_manager.full_name}</Text>
                  )}
                </View>
                {report.workers_present_count !== null && (
                  <View className="bg-orange-50 px-3 py-1.5 rounded-lg flex-row items-center">
                    <Ionicons name="people" size={14} color="#F97316" />
                    <Text className="text-brand-orange font-bold text-xs ml-1.5">{report.workers_present_count} Workers</Text>
                  </View>
                )}
              </View>

              <View className="mb-4">
                <Text className="text-gray-400 text-xs font-bold uppercase mb-2 tracking-wider">Work Completed</Text>
                <Text className="text-gray-700 leading-relaxed">{report.work_completed}</Text>
              </View>

              {report.blockers ? (
                <View className="bg-red-50 p-4 rounded-xl border border-red-100 mb-4 flex-row">
                  <Ionicons name="warning" size={16} color="#DC2626" className="mt-0.5 mr-2" />
                  <View className="flex-1">
                    <Text className="text-red-800 font-bold text-xs uppercase mb-1">Blockers / Issues</Text>
                    <Text className="text-red-700 text-sm leading-relaxed">{report.blockers}</Text>
                  </View>
                </View>
              ) : null}

              {report.photos && report.photos.length > 0 && (
                <View>
                  <Text className="text-gray-400 text-xs font-bold uppercase mb-2 tracking-wider">Attachments</Text>
                  <ScrollView horizontal showsHorizontalScrollIndicator={false} className="flex-row">
                    {report.photos.map((photo, index) => (
                      <View key={index} className="w-24 h-24 mr-3 bg-gray-100 rounded-xl overflow-hidden border border-gray-200">
                        <Image source={{ uri: photo }} className="w-full h-full" resizeMode="cover" />
                      </View>
                    ))}
                  </ScrollView>
                </View>
              )}
            </View>
          ))
        )}
      </ScrollView>
    </View>
  );
}

