        table: 'site_reports',
        filter: `project_id=eq.${projectId}`,
      }, () => loadData())
      .subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [projectId, loadData]);

  const formatDate = (dateStr: string) =>
    new Date(dateStr).toLocaleDateString('en-LK', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric' });

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav title="Daily Site Reports" showAction={false} />

      <ScrollView className="flex-1 p-6" showsVerticalScrollIndicator={false}>
        <Text className="text-2xl font-bold text-gray-800 mb-6">Site Reports History</Text>

        {loading ? (
          <View className="py-10 items-center justify-center">
            <ActivityIndicator color="#F97316" size="large" />
          </View>
        ) : reports.length === 0 ? (
          <View className="bg-white border border-gray-100 rounded-2xl p-10 items-center justify-center">
            <Ionicons name="document-text-outline" size={48} color="#D1D5DB" />
            <Text className="text-gray-400 font-bold mt-4 text-center">No reports yet</Text>
            <Text className="text-gray-400 text-sm mt-2 text-center">Your site manager hasn't submitted any daily reports.</Text>
          </View>
        ) : (
          reports.map(report => (
            <View key={report.id} className="bg-white border border-gray-100 rounded-2xl p-6 mb-6 shadow-sm">
              <View className="flex-row justify-between items-start border-b border-gray-50 pb-4 mb-4">
                <View>
                  <Text className="text-gray-800 font-bold text-lg">{formatDate(report.date)}</Text>
                  {report.site_manager && (
                    <Text className="text-gray-500 mt-1 text-xs">Submitted by: {report.site_manager.full_name}</Text>
                  )}
                </View>
                {report.workers_present_count !== null && (
                  <View className="bg-orange-50 px-3 py-1.5 rounded-lg flex-row items-center">
                    <Ionicons name="people" size={14} color="#F97316" />
                    <Text className="text-brand-orange font-bold text-xs ml-1.5">{report.workers_present_count} Workers</Text>
                  </View>
                )}
              </View>

              <View className="mb-4">
                <Text className="text-gray-400 text-xs font-bold uppercase mb-2 tracking-wider">Work Completed</Text>
                <Text className="text-gray-700 leading-relaxed">{report.work_completed}</Text>
              </View>

              {report.blockers ? (
                <View className="bg-red-50 p-4 rounded-xl border border-red-100 mb-4 flex-row">
                  <Ionicons name="warning" size={16} color="#DC2626" className="mt-0.5 mr-2" />
                  <View className="flex-1">
                    <Text className="text-red-800 font-bold text-xs uppercase mb-1">Blockers / Issues</Text>
                    <Text className="text-red-700 text-sm leading-relaxed">{report.blockers}</Text>
                  </View>
                </View>
              ) : null}

              {report.photos && report.photos.length > 0 && (
                <View>
                  <Text className="text-gray-400 text-xs font-bold uppercase mb-2 tracking-wider">Attachments</Text>
                  <ScrollView horizontal showsHorizontalScrollIndicator={false} className="flex-row">
                    {report.photos.map((photo, index) => (
                      <View key={index} className="w-24 h-24 mr-3 bg-gray-100 rounded-xl overflow-hidden border border-gray-200">
                        <Image source={{ uri: photo }} className="w-full h-full" resizeMode="cover" />
                      </View>
                    ))}
                  </ScrollView>
                </View>
              )}
            </View>
          ))
        )}
      </ScrollView>
    </View>
  );
}

// Modified for Expo Go mobile compatibility
import React, { useCallback, useMemo, useState } from 'react';
import { View, ScrollView, ActivityIndicator, Text, Pressable } from 'react-native';
import { useRouter } from 'expo-router';
import { TopNav } from '@/components/common/TopNav';
import { StatCard } from '../../components/common/StatCard';
import { AnimatedCard } from '../../components/common/AnimatedCard';
import { GlobalSearchDropdown } from '../../components/common/GlobalSearchDropdown';
import { SupplierOrdersTable } from '../../components/supplier/SupplierOrdersTable';
import { SupplierAlertsPanel } from '../../components/supplier/SupplierAlertsPanel';
import { SupplierPendingDeliveries } from '../../components/supplier/SupplierPendingDeliveries';
import { Ionicons } from '@expo/vector-icons';
import { useResponsive } from '../../hooks/useResponsive';
import {
  useSupplierOrders,
  deriveSupplierStats,
  matchesSupplierSearch,
  buildOrderSuggestions,
  PO_STATUS,
} from '../../hooks/useSupplierOrders';

const OPEN_STATUSES: string[] = [PO_STATUS.PENDING, PO_STATUS.SUGGESTED, PO_STATUS.CONFIRMED, PO_STATUS.DELIVERED];
const DONE_STATUSES: string[] = [PO_STATUS.DELIVERED, PO_STATUS.RECEIVED];

export default function SupplierDashboardScreen() {
  const { isMobile } = useResponsive();
  const router = useRouter();
  // Single realtime source for every widget on this screen.
  const { orders, projects, stats: globalStats, loading, lastUpdated, refresh } = useSupplierOrders();
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);

  const stats = {
    pendingOrders: globalStats.newOrders.length,
    confirmedOrders: globalStats.pendingDeliveries.length,
    lateDeliveries: globalStats.late.length,
    totalRevenue: globalStats.totalRevenue,
  };

  // Panels respect the project chip + search box; stat cards always show the full picture.
  const panelStats = useMemo(() => {
    const scoped = orders.filter(o =>
      (!selectedProjectId || o.project_id === selectedProjectId) && matchesSupplierSearch(o, searchQuery)
    );
    return deriveSupplierStats(scoped);
  }, [orders, selectedProjectId, searchQuery]);

  const assignedProjects = useMemo(() => {
    const map = new Map<string, { id: string; name: string; location: string }>();
    projects.forEach(p => map.set(p.id, p));
    // Include projects the supplier has orders for even if no explicit role assignment exists.
    orders.forEach(o => {
      if (o.project_id && !map.has(o.project_id)) {
        map.set(o.project_id, { id: o.project_id, name: o.project_name, location: (o as any).project_location || '' });
      }
    });
    return Array.from(map.values()).map(p => {
      const pOrders = orders.filter(o => o.project_id === p.id);
      const delivered = pOrders.filter(o => DONE_STATUSES.includes(o.status));
      const last = delivered.length > 0
        ? new Date(Math.max(...delivered.map(o => new Date(o.updated_at || o.created_at).getTime())))
        : null;
      return {
        ...p,
        openCount: pOrders.filter(o => OPEN_STATUSES.includes(o.status)).length,
        lastDelivery: last ? last.toDateString() : 'Never',
      };
    });
  }, [projects, orders]);

  const getSuggestions = useCallback((q: string) => buildOrderSuggestions(orders, q), [orders]);

  const handleOrderAction = () => { refresh(); };

  const formatCurrency = (amount: number) => {
    if (amount >= 1000000) return `Rs. ${(amount / 1000000).toFixed(1)}M`;
    if (amount >= 1000) return `Rs. ${(amount / 1000).toFixed(1)}K`;
    return `Rs. ${amount}`;
  };

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav 
        title="Supplier Dashboard" 
        actionLabel="Refresh" 
        onActionPress={refresh} 
      />

      {loading ? (
        <View className="flex-1 items-center justify-center">
          <ActivityIndicator size="large" color="#F97316" />
        </View>
      ) : (
        <ScrollView className="flex-1 p-6" showsVerticalScrollIndicator={false} keyboardShouldPersistTaps="handled">
          {/* Scoped search: in normal flow, scrolls with the page */}
          <View style={{ zIndex: 5, position: 'relative' }} className="mb-6">
            <GlobalSearchDropdown
              placeholder="Search your orders by PO, material or project..."
              value={searchQuery}
              onChangeText={setSearchQuery}
              getLocalResults={getSuggestions}
              onSelectResult={(item) => router.push(`/supplier/orders/${item.id}` as any)}
            />
            <View className="flex-row items-center mt-2">
              <View className="w-2 h-2 rounded-full bg-green-500 mr-2" />
              <Text className="text-[11px] text-gray-500">
                Live{lastUpdated ? ` · updated ${lastUpdated.toLocaleTimeString()}` : ''}
              </Text>
              {searchQuery.trim() !== '' && (
                <Text className="text-[11px] text-brand-orange ml-3">Panels filtered by "{searchQuery}"</Text>
              )}
            </View>
          </View>

          {/* Top Stat Cards Row */}
          <View className={isMobile ? "flex-row flex-wrap -mx-2 mb-6" : "flex-row gap-4 mb-6"}>
            <AnimatedCard delay={100} style={isMobile ? { width: '50%', paddingHorizontal: 8, marginBottom: 16 } : { flex: 1 }}>
              <StatCard 
                label="New Orders" 
                value={stats.pendingOrders.toString()} 
                indicatorText="Requires approval" 
                indicatorType="warning" 
              />
            </AnimatedCard>
            <AnimatedCard delay={200} style={isMobile ? { width: '50%', paddingHorizontal: 8, marginBottom: 16 } : { flex: 1 }}>
              <StatCard 
                label="In Transit" 
                value={stats.confirmedOrders.toString()} 
                indicatorText="Confirmed, awaiting dispatch" 
                indicatorType="success"
              />
            </AnimatedCard>
            <AnimatedCard delay={300} style={isMobile ? { width: '50%', paddingHorizontal: 8, marginBottom: 16 } : { flex: 1 }}>
              <StatCard 
                label="Late Deliveries" 
                value={stats.lateDeliveries.toString()} 
                indicatorText="Overdue items" 
                indicatorType={stats.lateDeliveries > 0 ? "danger" : "success"} 
                icon={<Ionicons name={stats.lateDeliveries > 0 ? "warning" : "checkmark-circle"} size={16} color={stats.lateDeliveries > 0 ? "#EF4444" : "#10B981"} />}
              />
            </AnimatedCard>
            <AnimatedCard delay={400} style={isMobile ? { width: '50%', paddingHorizontal: 8, marginBottom: 16 } : { flex: 1 }}>
              <StatCard 
                label="Total Revenue" 
                value={formatCurrency(stats.totalRevenue)} 
                indicatorText="Confirmed, delivered & received" 
              />
            </AnimatedCard>
          </View>

          {/* Assigned Projects Section */}
          <View className="mb-6">
            <View className="flex-row justify-between items-center mb-4">
              <Text className="text-lg font-bold text-gray-800">Projects I Supply</Text>
              {selectedProjectId && (
                 <Pressable onPress={() => setSelectedProjectId(null)}>
                   <Text className="text-brand-orange font-bold text-sm">Clear Filter</Text>
                 </Pressable>
              )}
            </View>

            {assignedProjects.length === 0 ? (
              <View className="bg-white rounded-2xl shadow-sm border border-gray-100 p-8 items-center justify-center">
                <Ionicons name="business-outline" size={48} color="#D1D5DB" className="mb-4" />
                <Text className="text-gray-500 font-medium">Not currently assigned to any projects.</Text>
              </View>
            ) : (
              <View className="flex-row flex-wrap -mx-2">
                {assignedProjects.map(proj => (
                  <View key={proj.id} style={{ width: isMobile ? '100%' : '33.333%', paddingHorizontal: 8, marginBottom: 16, minWidth: 0 }}>
                    <Pressable 
                      onPress={() => setSelectedProjectId(proj.id === selectedProjectId ? null : proj.id)}
                      className={`bg-white rounded-2xl shadow-sm border p-4 ${proj.id === selectedProjectId ? 'border-brand-orange bg-orange-50' : 'border-gray-100'}`}
                      style={{ minHeight: 130 }}
                    >
                      <View className="flex-row items-start mb-3">
                        <View className={`w-9 h-9 rounded-full items-center justify-center mr-3 ${proj.id === selectedProjectId ? 'bg-orange-100' : 'bg-blue-50'}`}>
                          <Ionicons name="construct" size={16} color={proj.id === selectedProjectId ? "#F97316" : "#3B82F6"} />
                        </View>
                        <View style={{ flex: 1, minWidth: 0 }}>
                          <Text className="font-bold text-gray-800" numberOfLines={1}>{proj.name}</Text>
                          <Text className="text-xs text-gray-400" numberOfLines={2}>{proj.location}</Text>
                        </View>
                      </View>
                      <View className="flex-row justify-between mb-1">
                        <Text className="text-sm text-gray-500">Open Orders:</Text>
                        <Text className="text-sm font-bold text-gray-800">{proj.openCount}</Text>
                      </View>
                      <View className="flex-row justify-between">
                        <Text className="text-sm text-gray-500">Last Delivery:</Text>
                        <Text className="text-sm font-medium text-gray-800" numberOfLines={1}>{proj.lastDelivery}</Text>
                      </View>
                    </Pressable>
                  </View>
                ))}
              </View>
            )}
          </View>

          {/* Center Row: Orders & Alerts */}
          <View className={isMobile ? "flex-col gap-6 mb-6" : "flex-row gap-6 mb-6"}>
            {/* Main Content Area (Orders) */}
            <View className="flex-[2] w-full">
              <SupplierOrdersTable
                orders={panelStats.incoming}
                onOrderAction={handleOrderAction}
                onOpenOrder={(id) => router.push(`/supplier/orders/${id}` as any)}
              />
            </View>
            
            {/* Side Panel (Late Alerts & Deliveries) */}
            <View className="flex-[1] w-full">
              <SupplierPendingDeliveries orders={panelStats.pendingDeliveries} onOpenOrder={(id) => router.push(`/supplier/orders/${id}` as any)} />
              <SupplierAlertsPanel orders={panelStats.late} />
            </View>
          </View>
        </ScrollView>
      )}
    </View>
  );
}

import { ModalViewport } from '@/components/common/ModalViewport';
import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, ActivityIndicator, Pressable, Alert, Platform } from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { supabase } from '../../../lib/supabase';
import { TopNav } from '@/components/common/TopNav';
import { Ionicons, FontAwesome5 } from '@expo/vector-icons';
import { format } from 'date-fns';
import { ChatWidget } from '../../../components/shared/ChatWidget';
import { sendSystemNotification } from '../../../utils/notifications';
import { api } from '../../../services/api';
import { Modal, TextInput } from 'react-native';

const SuggestModal = ({ visible, order, onClose, onSubmit }: any) => {
  const [qty, setQty] = useState('');
  const [date, setDate] = useState('');
  const [price, setPrice] = useState('');
  const [notes, setNotes] = useState('');

  useEffect(() => {
    if (order) {
      setQty((order.suggested_quantity || order.quantity_ordered)?.toString() || '');
      setDate(order.suggested_date || order.expected_date || '');
      setPrice(order.suggested_price ? order.suggested_price.toString() : (order.unit_price ? order.unit_price.toString() : ''));
      setNotes('');
    }
  }, [order]);

  if (!visible || !order) return null;

  return (
    <Modal visible={visible} transparent animationType="fade" onRequestClose={onClose}>
      <ModalViewport>
        <ScrollView keyboardShouldPersistTaps="handled" nestedScrollEnabled style={{ flexGrow: 0, flexShrink: 1 }} contentContainerStyle={{ padding: 24 }} className="bg-white rounded-2xl w-full max-w-md max-h-full">
          <Text className="text-xl font-bold text-brand-text mb-4">Counter-Offer</Text>
          <Text className="text-gray-500 mb-4 text-sm">Propose a different quantity, date, or price.</Text>

          <Text className="font-semibold text-gray-700 mb-1">Suggested Quantity</Text>
          <TextInput 
            className="border border-gray-300 rounded-lg p-3 mb-4 text-brand-text"
            keyboardType="numeric"
            value={qty}
            onChangeText={setQty}
          />

          <Text className="font-semibold text-gray-700 mb-1">Suggested Date (YYYY-MM-DD)</Text>
          <TextInput 
            className="border border-gray-300 rounded-lg p-3 mb-4 text-brand-text"
            value={date}
            onChangeText={setDate}
          />

          <Text className="font-semibold text-gray-700 mb-1">Suggested Unit Price (LKR)</Text>
          <TextInput 
            className="border border-gray-300 rounded-lg p-3 mb-4 text-brand-text"
            keyboardType="numeric"
            value={price}
            onChangeText={setPrice}
          />

          <Text className="font-semibold text-gray-700 mb-1">Notes to Admin</Text>
          <TextInput 
            className="border border-gray-300 rounded-lg p-3 mb-6 text-brand-text h-20"
            multiline
            value={notes}
            onChangeText={setNotes}
          />

          <View className="flex-row justify-end space-x-3">
            <Pressable onPress={onClose} className="px-4 py-2">
              <Text className="text-gray-500 font-bold">Cancel</Text>
            </Pressable>
            <Pressable 
              onPress={() => onSubmit(order.id, parseFloat(qty), date, parseFloat(price), notes)} 
              className="bg-brand-warning px-6 py-2 rounded-lg"
            >
              <Text className="text-white font-bold">Submit Counter</Text>
            </Pressable>
          </View>
        </ScrollView>
      </ModalViewport>
    </Modal>
  );
};

export default function AdminMaterialsOrdersIdPage() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const router = useRouter();

  const [order, setOrder] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState(false);
  const [suggestModalVisible, setSuggestModalVisible] = useState(false);
  const [unitPrice, setUnitPrice] = useState<string>('');
  const [currentUserId, setCurrentUserId] = useState('');
  useEffect(() => { supabase.auth.getSession().then(({data}) => setCurrentUserId(data.session?.user.id || '')); }, []);

  const fetchOrder = async () => {
    try {
      const { data, error } = await supabase
        .from('purchase_orders')
        .select(`
          *,
          project:projects(name, location)
        `)
        .eq('id', id)
        .single();
        
      if (error) throw error;

      let orderData = data;
      if (!orderData.project && orderData.project_id) {
        try {
           const extra = await api.projects.bulkNames([orderData.project_id]);
           if (extra && extra.length > 0) {
             orderData.project = extra[0];
           }
        } catch (e) {
           console.warn("Failed to fetch project via bulkNames", e);
        }
      }

      setOrder(orderData);
      if (orderData.unit_price) setUnitPrice(orderData.unit_price.toString());
      else setUnitPrice('');
    } catch (err: any) {
      const msg = err.message || err.detail || 'Failed to fetch order details';
      if (Platform.OS === 'web') window.alert(msg);
      else Alert.alert('Error', msg);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOrder();
  }, [id]);

  const handleUpdateStatus = async (newStatus: 'Confirmed' | 'Rejected' | 'Delivered' | 'Received') => {
    // Platform-safe confirm dialog
    const confirmed = Platform.OS === 'web'
      ? window.confirm(`Are you sure you want to mark this order as ${newStatus}?`)
      : await new Promise<boolean>((resolve) => {
          Alert.alert(
            'Confirm Action',
            `Are you sure you want to mark this order as ${newStatus}?`,
            [
              { text: 'Cancel', style: 'cancel', onPress: () => resolve(false) },
              { text: 'Yes', onPress: () => resolve(true) }
            ]
          );
        });

    if (!confirmed) return;

    setActionLoading(true);
    try {
      if (!id) throw new Error('Order id is required');
      if (newStatus === 'Confirmed') {
         if (!unitPrice || parseFloat(unitPrice) <= 0) {
            const msg = 'Please enter a valid unit price before confirming.';
            if (Platform.OS === 'web') window.alert(msg);
            else Alert.alert('Error', msg);
            setActionLoading(false);
            return;
         }
         await api.purchaseOrders.approve(id, { unit_price: parseFloat(unitPrice) });
      }
      if (newStatus === 'Rejected') await api.purchaseOrders.reject(id);
      if (newStatus === 'Delivered') await api.purchaseOrders.deliver(id);
      if (newStatus === 'Received') await api.purchaseOrders.receive(id);

      if (Platform.OS === 'web') window.alert(`Order marked as ${newStatus}!`);
      else Alert.alert('Success', `Order marked as ${newStatus}!`);

      // Refresh data
      fetchOrder();
    } catch (err: any) {
      const msg = err.message || 'Failed to update status';
      if (Platform.OS === 'web') window.alert(msg);
      else Alert.alert('Error', msg);
    } finally {
      setActionLoading(false);
    }
  };

  const handleSuggestSubmit = async (orderId: string, qty: number, date: string, price: number, notes: string) => {
    try {
      setActionLoading(true);
      setSuggestModalVisible(false);
      await api.purchaseOrders.suggest(orderId, {
        suggested_quantity: qty,
        suggested_date: date,
        suggested_price: price,
        supplier_notes: notes
      });
      fetchOrder();
    } catch (err: any) {
      const msg = err.message || err.detail || 'Failed to submit suggestion';
      if (Platform.OS === 'web') window.alert(msg);
      else Alert.alert('Error', msg);
    } finally {
      setActionLoading(false);
    }
  };


  if (loading) {
    return (
      <View className="flex-1 bg-brand-light items-center justify-center">
        <ActivityIndicator size="large" color="#F97316" />
      </View>
    );
  }

  if (!order) {
    return (
      <View className="flex-1 bg-brand-light">
        <TopNav title="Order Not Found" showAction={false} />
        <View className="flex-1 items-center justify-center">
          <Text className="text-gray-500">The requested order could not be found.</Text>
          <Pressable onPress={() => router.back()} className="mt-4 bg-brand-orange px-6 py-2 rounded-lg">
            <Text className="text-white font-bold">Go Back</Text>
          </Pressable>
        </View>
      </View>
    );
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Delivered': return 'bg-green-100 text-green-700 border-green-200';
      case 'Pending Delivery': return 'bg-orange-100 text-orange-700 border-orange-200';
      case 'Confirmed': return 'bg-blue-100 text-blue-700 border-blue-200';
      case 'Rejected': case 'Cancelled': return 'bg-red-100 text-red-700 border-red-200';
      default: return 'bg-gray-100 text-gray-700 border-gray-200';
    }
  };

  const isCompleted = order.status === 'Received' || order.status === 'Rejected' || order.status === 'Cancelled';

  // Parse negotiation log
  let negotiationLog: any[] = [];
  try {
    if (order.supplier_notes) {
      const parsed = JSON.parse(order.supplier_notes);
      if (Array.isArray(parsed)) {
        negotiationLog = parsed;
      }
    }
  } catch (e) {}

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav title={`Order ${order.po_number}`} showAction={false} />
      
      <ScrollView className="flex-1 p-6" showsVerticalScrollIndicator={false}>
        <View className="max-w-[700px] w-full mx-auto">
          
          <Pressable onPress={() => router.back()} className="flex-row items-center mb-6 self-start">
            <Ionicons name="arrow-back" size={20} color="#6B7280" />
            <Text className="text-gray-500 font-semibold ml-2">Back to Orders</Text>
          </Pressable>

          {/* Main Details Card */}
          <View className="bg-white rounded-2xl shadow-sm border border-gray-100 p-8 mb-6">
            <View className="flex-row justify-between items-start mb-8 pb-6 border-b border-gray-100">
              <View>
                <Text className="text-3xl font-bold text-gray-800 mb-2">{order.po_number}</Text>
                <Text className="text-gray-500 flex-row items-center">
                  <Ionicons name="calendar-outline" size={14} /> Created on {format(new Date(order.created_at), 'MMM dd, yyyy')}
                </Text>
              </View>
              <View className={`px-4 py-2 rounded-lg border ${getStatusColor(order.status)}`}>
                <Text className="font-bold uppercase tracking-wide text-xs">{order.status}</Text>
              </View>
            </View>

            <View className="flex-row flex-wrap mb-8">
              <View className="w-1/2 mb-6">
                <Text className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-1">Supplier</Text>
                <View className="flex-row items-center">
                  <View className="w-8 h-8 rounded-full bg-blue-50 items-center justify-center mr-3">
                    <FontAwesome5 name="truck" size={12} color="#3B82F6" />
                  </View>
                  <Text className="text-gray-800 font-medium text-base">{order.supplier_name || 'Unknown'}</Text>
                </View>
              </View>

              <View className="w-1/2 mb-6 pr-4" style={{ minWidth: 0 }}>
                <Text className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-1">Project Site</Text>
                <View className="flex-row items-center">
                  <View className="w-8 h-8 rounded-full bg-emerald-50 items-center justify-center mr-3">
                    <FontAwesome5 name="hard-hat" size={12} color="#10B981" />
                  </View>
                  <View style={{ flex: 1, minWidth: 0 }}>
                    <Text className="text-gray-800 font-medium text-base" style={{ flexShrink: 1 }}>{order.project?.name || 'Unknown Project'}</Text>
                    {order.project?.location ? (
                      <Text className="text-xs text-gray-500 mt-0.5" style={{ flexShrink: 1 }} numberOfLines={3}>{order.project.location}</Text>
                    ) : null}
                  </View>
                </View>
              </View>

              <View className="w-1/2">
                <Text className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-1">Expected Delivery</Text>
                <Text className="text-gray-800 font-medium text-base">
                  {order.expected_date ? format(new Date(order.expected_date), 'MMM dd, yyyy') : 'TBD'}
                </Text>
              </View>

              <View className="w-1/2">
                <Text className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-1">Total Cost</Text>
                <Text className="text-brand-orange font-bold text-xl">
                  Rs. {(order.total_price || 0).toLocaleString()}
                </Text>
              </View>
            </View>

            {/* Items Ordered Section */}
            <View className="bg-gray-50 rounded-xl p-6 border border-gray-100">
              <Text className="text-sm font-bold text-gray-700 mb-4 uppercase tracking-wider">Items Ordered</Text>
              <View className="flex-row justify-between items-center py-3 border-b border-gray-200 mb-2">
                <Text className="text-gray-800 font-medium flex-1">{order.items}</Text>
                <Text className="text-gray-500 w-24 text-right">Qty: {order.quantity_ordered}</Text>
                
                {order.status === 'Pending Delivery' ? (
                  <View className="w-32 flex-row items-center justify-end">
                    <Text className="text-gray-500 mr-2 font-bold">Rs.</Text>
                    <TextInput
                      className="border border-gray-300 rounded-lg bg-white p-2 w-24 text-right text-brand-text font-bold"
                      keyboardType="numeric"
                      value={unitPrice}
                      onChangeText={setUnitPrice}
                      placeholder="0.00"
                    />
                  </View>
                ) : (
                  <Text className="text-gray-800 font-bold w-32 text-right">Rs. {(order.unit_price || 0).toLocaleString()}</Text>
                )}
              </View>
              <View className="flex-row justify-between items-center pt-2">
                <Text className="text-gray-500 font-bold">Total</Text>
                <Text className="text-brand-orange font-bold text-lg">
                  Rs. {order.status === 'Pending Delivery' ? ((parseFloat(unitPrice) || 0) * (order.quantity_ordered || 0)).toLocaleString() : (order.total_price || 0).toLocaleString()}
                </Text>
              </View>
            </View>

            {negotiationLog.length > 0 && (
              <View className="mt-8">
                <Text className="text-lg font-bold text-gray-800 mb-4">Negotiation History</Text>
                <View className="border-l-2 border-gray-200 ml-3 pl-4">
                  {negotiationLog.map((event, idx) => (
                    <View key={idx} className="mb-4 relative">
                      <View className={`absolute -left-6 w-4 h-4 rounded-full ${event.role === 'supplier' ? 'bg-blue-500' : 'bg-green-500'} border-4 border-white`} />
                      <Text className="text-xs text-gray-400 mb-1">{event.timestamp ? format(new Date(event.timestamp), 'MMM dd, yyyy h:mm a') : ''} • {event.role === 'supplier' ? 'You' : 'Admin/PM'}</Text>
                      <View className="bg-gray-50 p-3 rounded-lg border border-gray-100">
                        <Text className="font-bold text-gray-700 capitalize mb-1">{event.action}</Text>
                        {event.quantity && <Text className="text-sm text-gray-600">Qty: {event.quantity}</Text>}
                        {event.suggested_quantity && <Text className="text-sm text-gray-600">Qty: {event.suggested_quantity}</Text>}
                        {event.unit_price && <Text className="text-sm text-gray-600">Price: Rs. {event.unit_price}</Text>}
                        {event.suggested_price && <Text className="text-sm text-gray-600">Price: Rs. {event.suggested_price}</Text>}
                        {event.date && <Text className="text-sm text-gray-600">Date: {event.date}</Text>}
                        {event.suggested_date && <Text className="text-sm text-gray-600">Date: {event.suggested_date}</Text>}
                        {event.note && <Text className="text-sm text-gray-500 italic mt-2">"{event.note}"</Text>}
                      </View>
                    </View>
                  ))}
                </View>
              </View>
            )}

          </View>

          {/* Action Buttons Section */}
          {!isCompleted && (
            <View className="bg-white rounded-2xl shadow-sm border border-gray-100 p-8 flex-row justify-between items-center">
              <View className="flex-1 mr-4">
                <Text className="text-lg font-bold text-gray-800 mb-1">Update Order Status</Text>
                <Text className="text-gray-500 text-sm">Review the details above before confirming or rejecting this order.</Text>
              </View>
              
              <View className="flex-row gap-3">
                {order.status === 'Pending Delivery' ? <Pressable
                  disabled={actionLoading}
                  onPress={() => handleUpdateStatus('Rejected')}
                  className="bg-red-50 border border-red-200 px-6 py-3 rounded-lg mr-3"
                >
                  <Text className="text-red-600 font-bold">Reject</Text>
                </Pressable> : null}
                
                {order.status === 'Confirmed' ? <Pressable
                  disabled={actionLoading}
                  onPress={() => handleUpdateStatus('Delivered')}
                  className="bg-brand-orange shadow-sm px-6 py-3 rounded-lg flex-row items-center"
                >
                  {actionLoading && <ActivityIndicator size="small" color="white" className="mr-2" />}
                  <Text className="text-white font-bold">Mark Delivered</Text>
                </Pressable> : order.status === 'Pending Delivery' ? (
                  <>
                    <Pressable
                      disabled={actionLoading}
                      onPress={() => setSuggestModalVisible(true)}
                      className="bg-yellow-500 shadow-sm px-6 py-3 rounded-lg flex-row items-center mr-3"
                    >
                      <Text className="text-white font-bold">Counter Admin</Text>
                    </Pressable>
                    <Pressable
                      disabled={actionLoading}
                      onPress={() => handleUpdateStatus('Confirmed')}
                      className="bg-brand-orange shadow-sm px-6 py-3 rounded-lg flex-row items-center"
                    >
                      {actionLoading && <ActivityIndicator size="small" color="white" className="mr-2" />}
                      <Text className="text-white font-bold">Confirm Order</Text>
                    </Pressable>
                  </>
                ) : null}
              </View>
            </View>
          )}

        </View>
      </ScrollView>

      <SuggestModal 
        visible={suggestModalVisible}
        order={order}
        onClose={() => setSuggestModalVisible(false)}
        onSubmit={handleSuggestSubmit}
      />
    </View>
  );
}

import React, { useEffect, useState } from 'react';
import { View, Text, Pressable, ActivityIndicator } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { supabase } from '../../lib/supabase';

/**
 * CostBreakdown
 *
 * Shows the most recent estimation from the `estimations` table,
 * along with per-prediction feature contributions returned by
 * /api/ai/predict-cost (stored on the estimation record) and
 * a real confidence score.
 *
 * Props:
 *   refreshTrigger  — increment to re-fetch after a new estimate is created
 *   featureContributions — optional array from the predict-cost response
 *   confidence       — optional 0-100 confidence from the predict-cost response
 */

type FeatureContrib = { name: string; value: number };

const SEGMENT_COLORS = [
  '#F97316', // brand-orange
  '#0F1117', // brand-dark
  '#EF4444', // brand-danger
  '#6B7280', // gray-500
  '#3B82F6', // blue
];

export const CostBreakdown = ({
  refreshTrigger = 0,
  featureContributions,
  confidence,
}: {
  refreshTrigger?: number;
  featureContributions?: FeatureContrib[];
  confidence?: number | null;
}) => {
  const [latestEstimate, setLatestEstimate] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let isMounted = true;
    const fetchLatest = async () => {
      try {
        const { data, error } = await supabase
          .from('estimations')
          .select('*')
          .order('created_at', { ascending: false })
          .limit(1);

        if (error) throw error;
        if (isMounted) setLatestEstimate(data?.[0] || null);
      } catch (err) {
        console.warn('Failed to load latest estimate', err);
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    fetchLatest();
    return () => { isMounted = false; };
  }, [refreshTrigger]);

  const formatCurrency = (amount: number) => {
    if (!amount) return 'Rs. 0';
    if (amount >= 1_000_000) return `Rs. ${(amount / 1_000_000).toFixed(1)}M`;
    if (amount >= 1_000) return `Rs. ${(amount / 1_000).toFixed(1)}K`;
    return `Rs. ${amount}`;
  };

  const cost = latestEstimate?.estimated_cost || 0;
  // Prefer prop (freshest prediction) over stored value
  const confidenceVal = confidence ?? latestEstimate?.confidence_score ?? null;

  // Feature contributions: prefer live prop, fall back to parsed JSON from project_name if available
  let parsedContribs: FeatureContrib[] | null = null;
  let explanation = "Illustrative split — generate a new estimate to see model-specific contributions";

  try {
    if (latestEstimate?.project_name) {
      const parsed = JSON.parse(latestEstimate.project_name);
      if (parsed.contributions) {
        parsedContribs = parsed.contributions;
      }
    }
  } catch (e) {
    // Not valid JSON, keep as null
  }

  const contribs: FeatureContrib[] = featureContributions || parsedContribs || [];

  if (contribs.length > 0) {
    explanation = `${contribs[0]?.name} weighted highest due to project size and quality tier`;
  }

  if (loading) {
    return (
      <View className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 flex-1 items-center justify-center min-h-[300px]">
        <ActivityIndicator color="#F97316" />
      </View>
    );
  }

  if (!latestEstimate) {
    return (
      <View className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 flex-1 items-center justify-center min-h-[300px]">
        <Ionicons name="calculator-outline" size={40} color="#E5E7EB" />
        <Text className="text-gray-400 mt-3 text-sm text-center">
          No estimates generated yet.{'\n'}Use the AI Estimator to create one.
        </Text>
      </View>
    );
  }

  const confidenceLabel =
    confidenceVal == null
      ? 'Not validated'
      : confidenceVal >= 75
      ? 'High'
      : confidenceVal >= 50
      ? 'Medium'
      : 'Low';

  const confidenceBg =
    confidenceVal == null
      ? 'bg-gray-100'
      : confidenceVal >= 75
      ? 'bg-green-50'
      : confidenceVal >= 50
      ? 'bg-yellow-50'
      : 'bg-red-50';

  const confidenceText =
    confidenceVal == null
      ? 'text-gray-500'
      : confidenceVal >= 75
      ? 'text-brand-success'
      : confidenceVal >= 50
      ? 'text-yellow-700'
      : 'text-brand-danger';

  return (
    <View className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 flex-1">
      {/* Header */}
      <View className="flex-row justify-between items-center mb-1">
        <Text className="text-lg font-bold text-brand-text">
          {contribs.length > 0 ? 'Feature Contributions' : 'Cost Breakdown'}
        </Text>
        <Pressable className="flex-row items-center border border-gray-200 px-3 py-1.5 rounded-full">
          <Ionicons name="time-outline" size={14} color="#6B7280" />
          <Text className="text-gray-600 text-xs font-semibold ml-1.5">Live Estimate</Text>
        </Pressable>
      </View>

      {contribs.length > 0 ? (
        <Text className="text-gray-400 text-xs mb-4">
          Which factors drove this specific prediction, ranked by contribution
        </Text>
      ) : (
        <Text className="text-gray-400 text-xs mb-4">
          Latest model estimate from saved history
        </Text>
      )}

      {/* Total Cost + Confidence */}
      <View className="flex-row items-center mb-6">
        <View className="flex-1">
          <Text className="text-gray-500 text-xs font-semibold uppercase mb-1">
            Estimated Total Cost
          </Text>
          <Text className="text-3xl font-bold text-brand-orange">
            {formatCurrency(cost)}
          </Text>
          <Text className="text-gray-400 text-[10px] mt-1">
            This is an estimate — confirm with a quantity surveyor.
          </Text>
        </View>

        <View className={`px-3 py-2 rounded-xl ${confidenceBg} ml-4 items-center`}>
          <Text className="text-gray-400 text-[10px] uppercase mb-0.5">Confidence</Text>
          <Text className={`font-bold text-sm ${confidenceText}`}>
            {confidenceVal != null ? `${Math.round(confidenceVal)}%` : '—'}
          </Text>
          <Text className={`text-[10px] font-semibold ${confidenceText}`}>
            {confidenceLabel}
          </Text>
        </View>
      </View>

      {/* Feature bar chart */}
      {contribs.length > 0 ? (
        <View className="border-t border-gray-100 pt-4">
          {contribs.slice(0, 5).map((feat, i) => (
            <View key={feat.name} className="mb-3">
              <View className="flex-row justify-between mb-1">
                <Text className="text-sm text-gray-700">{feat.name}</Text>
                <Text className="text-sm font-bold text-brand-text">{feat.value}%</Text>
              </View>
              <View className="w-full h-2 bg-gray-100 rounded-full overflow-hidden">
                <View
                  style={{
                    width: `${feat.value}%`,
                    height: '100%',
                    backgroundColor: SEGMENT_COLORS[i % SEGMENT_COLORS.length],
                    borderRadius: 4,
                  }}
                />
              </View>
            </View>
          ))}
          <Text className="text-gray-400 text-[10px] mt-2">
            Contribution percentages reflect this prediction's feature weights from the trained RandomForest.
          </Text>
        </View>
      ) : (
        /* Legacy static legend when no contribution data is available */
        <View className="flex-row flex-wrap justify-between pt-4 border-t border-gray-100">
          {[
            { label: 'Materials', pct: '42%', color: '#6B7280' },
            { label: 'Labour',    pct: '26%', color: '#0F1117' },
            { label: 'Equipment', pct: '16%', color: '#EF4444' },
            { label: 'Overhead',  pct: '16%', color: '#000' },
          ].map(item => (
            <View key={item.label} className="flex-row items-center w-[48%] mb-2">
              <View className="w-3 h-3 rounded-sm mr-2" style={{ backgroundColor: item.color }} />
              <Text className="text-xs text-gray-600 flex-1">{item.label}</Text>
              <Text className="text-xs font-bold text-brand-text">{item.pct}</Text>
            </View>
          ))}
          <Text className="text-gray-400 text-[10px] mt-2 w-full">
            Illustrative split — generate a new estimate to see model-specific contributions.
          </Text>
        </View>
      )}
    </View>
  );
};

import React, { useState } from 'react';
import { View, Text, Pressable, StyleSheet, ActivityIndicator, Platform } from 'react-native';
import { CameraView, useCameraPermissions } from 'expo-camera';
import { Ionicons } from '@expo/vector-icons';

type QRScannerProps = {
  onScan: (data: string) => void;
  onClose: () => void;
};

export const QRScanner = ({ onScan, onClose }: QRScannerProps) => {
  const [permission, requestPermission] = useCameraPermissions();
  const [scanned, setScanned] = useState(false);

  if (!permission) {
    return (
      <View className="flex-1 bg-black items-center justify-center">
        <ActivityIndicator size="large" color="#F97316" />
      </View>
    );
  }

  if (!permission.granted) {
    return (
      <View className="flex-1 bg-black items-center justify-center p-8">
        <Text className="text-white text-center mb-6 text-lg font-bold">
          We need your permission to show the camera
        </Text>
        {Platform.OS === 'web' && (
          <Text className="text-orange-400 text-center mb-6 text-sm px-4">
            Note: Camera access on Web requires HTTPS or a secure localhost context. If clicking 'Grant' does nothing, check your browser permissions.
          </Text>
        )}
        <Pressable 
          onPress={async () => {
            try {
              await requestPermission();
            } catch (err: any) {
              if (Platform.OS === 'web') window.alert("Browser blocked camera access.");
            }
          }}
          className="bg-brand-orange px-6 py-3 rounded-xl"
        >
          <Text className="text-white font-bold">Grant Permission</Text>
        </Pressable>
        <Pressable onPress={onClose} className="mt-8">
          <Text className="text-gray-400 font-semibold">Cancel</Text>
        </Pressable>
      </View>
    );
  }

  const handleBarcodeScanned = ({ type, data }: { type: string, data: string }) => {
    if (scanned) return;
    setScanned(true);
    onScan(data);
  };

  return (
    <View className="flex-1 bg-black">
      <CameraView
        style={StyleSheet.absoluteFillObject}
        barcodeScannerSettings={{
          barcodeTypes: ["qr"],
        }}
        onBarcodeScanned={scanned ? undefined : handleBarcodeScanned}
      >
        <View className="flex-1">
          {/* Overlay mask */}
          <View className="flex-row items-center justify-between p-6 pt-12 bg-black/40">
            <Text className="text-white font-bold text-xl">ස්කෑන් කරන්න (Scan QR)</Text>
            <Pressable onPress={onClose} className="w-11 h-11 rounded-full bg-white/20 items-center justify-center">
              <Ionicons name="close" size={24} color="white" />
            </Pressable>
          </View>
          
          <View className="flex-1 items-center justify-center">
            {/* Viewfinder frame */}
            <View className="w-64 h-64 border-2 border-brand-orange rounded-3xl items-center justify-center relative">
              <View className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-brand-orange rounded-tl-3xl" />
              <View className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 border-brand-orange rounded-tr-3xl" />
              <View className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 border-brand-orange rounded-bl-3xl" />
              <View className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-brand-orange rounded-br-3xl" />
              <View className="absolute w-full h-[2px] bg-brand-orange/50 top-1/2 shadow-lg shadow-brand-orange/50" />
            </View>
            <Text className="text-white text-center mt-8 px-8 opacity-80">
              Point your camera at the Site QR Code to check in or out.
            </Text>
          </View>
        </View>
      </CameraView>
    </View>
  );
};
